function richRegister(topic,slug,title,level,context,representation,build,verify,head=false){
  const [domain,topicId]=RICH_TOPICS[topic],id=`rich.${topic}.${slug}`;
  const spec={id,title,domain,topic:topicId,demand:({1:'L1_REP',2:'L2_REP',3:'L3_COMPOSE',4:'L4_TRANSFER',5:'L5_COMPLEX'})[level],structure:`${topic}:${slug}`,action:'solve-'+slug,context,representation,reason:title+'. De vraag combineert alleen de vermelde gegevens; het niveau is een ontwerpinschatting.',modes:head?['head','non']:['non'],build,verify,lesson:topic};
  spec.equivalentTo=RICH_EXISTING_EQUIVALENTS[id]||null;
  RICH_FAMILIES.push(spec);REASONING_DESIGNS.push(spec);
}
function richNum(prompt,answer,explanation,data,extra={}){return reasoningNum(prompt,answer,explanation,{rule:'rich',values:data},{tolerance:1e-8,...extra})}
function richChoice(prompt,correct,others,explanation,data,extra={}){return reasoningChoice(prompt,correct,others,explanation,{rule:'rich',values:data},extra)}
function richTable(title,rows,headers=['Gegeven','Waarde']){return reasoningTable(headers,rows,title)}
function richStrip(n,total,label='Gekleurd deel'){
  return reasoningSvg(`<text x="30" y="28" font-size="19">${escapeHtml(label)}</text>`+Array.from({length:total},(_,i)=>`<rect x="${30+420*i/total}" y="50" width="${420/total}" height="55" fill="${i<n?'#24846b':'#fff'}" stroke="#123b5d" stroke-width="2"/>`).join(''),`${label}: ${n} van ${total} gelijke vakken zijn gekleurd.`,135);
}
function richRect(l,w,unit='m',title='Rechthoek'){
 return reasoningSvg(`<text x="25" y="27" font-size="19">${escapeHtml(title)}</text><rect x="75" y="60" width="310" height="110" fill="#eaf6ff" stroke="#123b5d" stroke-width="3"/><text x="230" y="200" text-anchor="middle" font-size="20">${escapeHtml(String(l))} ${unit}</text><text x="395" y="115" font-size="20">${escapeHtml(String(w))}</text><text x="395" y="142" font-size="18">${unit}</text>`,`${title}: lengte ${l} ${unit}, breedte ${w} ${unit}. Schematisch, niet op schaal.`,225);
}
function richTimeline(labels){return reasoningSvg(`<line x1="40" y1="75" x2="440" y2="75" stroke="#123b5d" stroke-width="3"/>`+labels.map((t,i)=>`<circle cx="${40+i*400/(labels.length-1)}" cy="75" r="6" fill="#123b5d"/><text x="${40+i*400/(labels.length-1)}" y="${i%2?115:45}" text-anchor="middle" font-size="18">${escapeHtml(t)}</text>`).join(''),labels.join(' → ')+'. Schematische tijdlijn.',145)}
function richClock(minutes){return `${String(Math.floor(minutes/60)%24).padStart(2,'0')}.${String(minutes%60).padStart(2,'0')}`}
function richFraction(n,d){return {allowFraction:true,answerDisplay:reasoningFraction(n,d)}}
// A1 — plaatswaarde: ook ontbrekende gegevens, nauwkeurigheid en afleesstappen.
richRegister('A1','expanded-decimal','Een decimaal uit plaatswaardekaarten opbouwen',2,'plaatswaardekaarten','table',()=>{const a=randInt(1,9),b=randInt(1,9),c=randInt(1,9);return richNum('Welk getal vormen deze kaarten samen?',a+b/10+c/1000,`Tel de bijdragen op: ${a} + ${fmt(b/10)} + ${fmt(c/1000)} = ${fmt(a+b/10+c/1000)}. De honderdstenplaats blijft nul.`,{a,b,c},{visual:richTable('Plaatswaardekaarten',[['Eenheden',a],['Tienden',b],['Duizendsten',c]])})},v=>(1000*v.a+100*v.b+v.c)/1000,true);
richRegister('A1','digit-replacement','Het effect van één vervangen cijfer',2,'magazijncode','text',()=>{const a=randInt(2,5),b=randInt(6,9),n=randInt(1,8)*1000+a*100+randInt(10,99);return richNum(`In het getal ${n} wordt alleen het honderdtallencijfer ${a} vervangen door ${b}. Hoeveel wordt het getal groter?`,(b-a)*100,`Er komen ${b-a} honderdtallen bij: ${b-a} × 100 = ${(b-a)*100}.`,{a,b,n})},v=>v.n-v.a*100+v.b*100-v.n,true);
richRegister('A1','decimal-midpoint','Het midden tussen twee decimalen vinden',2,'meetlat','numberline',()=>{const a=randInt(10,60),gap=pick([2,4,6,8]);return richNum('P ligt precies halverwege de twee aangegeven waarden. Welke waarde hoort bij P?',(a+gap/2)/10,`De afstand is ${fmt(gap/10)}. De helft daarvan is ${fmt(gap/20)}. Tel die op bij ${fmt(a/10)}.`,{a,gap},{visual:reasoningNumberLine(a,a+gap,10,1,2)})},v=>(v.a+(v.a+v.gap))/20,true);
richRegister('A1','rounding-lower','De ondergrens van een afgerond meetgetal',3,'meetrapport','table',()=>{const a=randInt(12,80)*10;return richNum('Een lengte in hele centimeters is afgerond op tientallen. Bij een halve stap wordt omhoog afgerond. Wat is de kleinste mogelijke oorspronkelijke lengte?',a-5,`Vanaf ${a-5} cm wordt naar ${a} cm afgerond. ${a-6} cm wordt nog naar ${a-10} cm afgerond.`,{a},{unit:'cm',visual:richTable('Meetrapport',[['Afgeronde lengte',`${a} cm`]])})},v=>{for(let n=v.a-10;n<v.a+10;n++)if(Math.round(n/10)*10===v.a)return n},true);
richRegister('A1','rounding-count','Hoeveel gehele waarden dezelfde afronding hebben',3,'bezoekerstellers','text',()=>{const step=pick([10,100,1000]),a=step*randInt(3,9);return richNum(`Een bezoekersaantal wordt afgerond op ${step===10?'tientallen':step===100?'honderdtallen':'duizendtallen'} en wordt ${a}. Bij een halve stap wordt omhoog afgerond. Hoeveel verschillende gehele bezoekersaantallen kunnen dit geweest zijn?`,step,`Van ${a-step/2} tot en met ${a+step/2-1} zijn er ${step} gehele aantallen. Tel beide grenzen mee.`,{step,a})},v=>{let c=0;for(let n=v.a-v.step;n<=v.a+v.step;n++)if(Math.round(n/v.step)*v.step===v.a)c++;return c},true);
richRegister('A1','decimal-completion','Een decimale afstand tot een grens aanvullen',2,'kilometerteller','table',()=>{const target=randInt(3,9),hundredths=randInt(12,89),now=target-hundredths/100;return richNum('Hoeveel kilometer ontbreekt nog tot de genoemde grens?',hundredths/100,`${target} − ${fmt(now,2)} = ${fmt(hundredths/100,2)} km. Vul de honderdsten aan tot een heel getal.`,{target,now},{unit:'km',visual:richTable('Afstand',[['Afgelegd',`${fmt(now,2)} km`],['Grens',`${target} km`]])})},v=>v.target-v.now,true);
richRegister('A1','bounded-number','Een getal met cijfer- en intervalvoorwaarden',3,'getallenraadsel','text',()=>{const a=randInt(2,8),b=randInt(3,8);return richNum(`Een getal heeft precies twee cijfers achter de komma. Het ligt tussen ${a} en ${a+1}. Het tiendencijfer is ${b}; het honderdste cijfer is 3 kleiner. Welk getal is het?`,a+b/10+(b-3)/100,`De eenheden zijn ${a}, de tienden ${b} en de honderdsten ${b-3}. Samen is dat ${fmt(a+b/10+(b-3)/100,2)}.`,{a,b})},v=>(100*v.a+10*v.b+(v.b-3))/100,true);
