richRegister('A1','rounding-sum-difference','Afronden vóór of na optellen vergelijken',3,'dagtellingen','table',()=>{const a=randInt(11,30)*10+4,b=randInt(11,30)*10+4;return richNum('Hoeveel groter is de uitkomst als je eerst de aantallen optelt en daarna afrondt op tientallen, dan wanneer je beide aantallen eerst afrondt en daarna optelt?',10,`${a} + ${b} = ${a+b}, afgerond ${Math.round((a+b)/10)*10}. Afzonderlijk afgerond krijg je ${a-4} + ${b-4} = ${a+b-8}. Het verschil is 10.`,{a,b},{visual:richTable('Exact geteld',[['Maandag',a],['Dinsdag',b]])})},v=>Math.round((v.a+v.b)/10)*10-Math.round(v.a/10)*10-Math.round(v.b/10)*10);
