richRegister('A3','minimum-multiple','Eerste veelvoud boven een voorraadgrens',3,'drukwerk','order',()=>{const pack=pick([6,8,12]),needed=randInt(5,12)*pack+randInt(1,pack-1);return richNum(`Folders worden uitsluitend in bundels van ${pack} geleverd. Je hebt minstens ${needed} folders nodig. Wat is het kleinste aantal folders dat je kunt bestellen?`,Math.ceil(needed/pack)*pack,`Zoek het eerste veelvoud van ${pack} dat minstens ${needed} is. Dat is ${Math.ceil(needed/pack)*pack}.`,{pack,needed})},v=>{let n=v.needed;while(n%v.pack)n++;return n},true);
richRegister('A3','temperature-start','Een negatieve beginwaarde terugvinden',2,'weer','timeline',()=>{const start=-randInt(2,9),rise=randInt(10,16),end=start+rise;return richNum(`De temperatuur is ${rise} °C gestegen. Nu is het ${end} °C. Wat was de begintemperatuur?`,start,`Maak de stijging ongedaan: ${end} − ${rise} = ${start} °C.`,{rise,end},{unit:'°C',visual:richTimeline(['? °C',`+${rise} °C`,`${end} °C`])})},v=>v.end-v.rise,true);
richRegister('A3','cross-zero-distance','Afstand tussen hoogtes boven en onder zeeniveau',2,'landschap','table',()=>{const a=randInt(5,30),b=randInt(2,12);return richNum('Hoeveel meter hoogteverschil is er tussen de twee locaties?',a+b,`Van −${b} naar zeeniveau is ${b} m; daarna nog ${a} m omhoog. Samen ${a+b} m.`,{a,b},{unit:'m',visual:richTable('Hoogtes ten opzichte van zeeniveau',[['Duin',`+${a} m`],['Polder',`−${b} m`]])})},v=>Math.abs(v.a-(-v.b)),true);
richRegister('A3','divisibility-add','Kleinste aanvulling tot deelbaarheid',2,'teamindeling','text',()=>{const size=randInt(4,9),n=randInt(4,9)*size+randInt(1,size-1);return richNum(`Er zijn ${n} deelnemers. Hoeveel moeten er minimaal bijkomen zodat iedereen in teams van precies ${size} kan worden ingedeeld?`,size-n%size,`Het volgende veelvoud van ${size} is ${Math.ceil(n/size)*size}. Dat vraagt ${size-n%size} extra deelnemers.`,{size,n})},v=>{let k=0;while((v.n+k)%v.size)k++;return k},true);
richRegister('A3','inclusive-count','Veelvouden binnen twee grenzen tellen',3,'toegangsnummer','text',()=>{const step=pick([4,5,6,8]),a=randInt(2,5)*step,b=a+randInt(4,8)*step;return richNum(`Hoeveel gehele nummers van ${a} tot en met ${b} zijn deelbaar door ${step}? Beide grenzen tellen mee.`,(b-a)/step+1,`De nummers beginnen bij ${a} en eindigen bij ${b}. Er zijn ${(b-a)/step} sprongen van ${step}, dus ${(b-a)/step+1} nummers.`,{step,a,b})},v=>Array.from({length:v.b-v.a+1},(_,i)=>v.a+i).filter(n=>n%v.step===0).length,true);
richRegister('A3','parity','Even of oneven na een combinatie',2,'getaleigenschappen','text',()=>{const n=randInt(2,9),answer='Oneven.';return richChoice(`Je neemt een willekeurig geheel getal, verdubbelt het en telt ${2*n+1} erbij op. Wat geldt altijd voor het resultaat?`,answer,['Even.','Soms even en soms oneven.','Altijd deelbaar door 4.'],'Een verdubbeld geheel getal is even. Een oneven getal erbij maakt het resultaat oneven.',{n})},v=>'Oneven.',true);
// A4 — volgorde, machten, wortels en redelijkheid.
richRegister('A4','square-side','Een zijde uit vierkante oppervlakte terugvinden',2,'moestuin','diagram',()=>{const side=randInt(4,15);return richNum('Dit tuinbed is een vierkant. Hoe lang is één zijde?',side,`Zoek het getal dat met zichzelf vermenigvuldigd ${side*side} geeft: ${side} × ${side} = ${side*side}.`,{area:side*side},{unit:'m',visual:richRect('?','?','m',`Oppervlakte ${side*side} m²`)})},v=>Math.sqrt(v.area),true);
richRegister('A4','square-growth','Het verschil tussen opeenvolgende kwadraten',3,'vierkante-vloer','text',()=>{const n=randInt(4,12);return richNum(`Een vierkante vloer van ${n} bij ${n} tegels wordt vergroot tot ${n+1} bij ${n+1} tegels. Hoeveel tegels komen erbij?`,2*n+1,`Oud: ${n*n}; nieuw: ${(n+1)**2}. Het verschil is ${2*n+1} tegels.`,{n})},v=>(v.n+1)**2-v.n**2,true);
richRegister('A4','root-bound','Een wortel tussen gehele getallen plaatsen',3,'wortels-schatten','text',()=>{const n=randInt(4,14),x=n*n+randInt(1,2*n);return richNum(`Wat is het grootste gehele getal dat kleiner is dan √${x}?`,n,`${n}² = ${n*n} en ${n+1}² = ${(n+1)**2}. De wortel ligt ertussen, dus het gevraagde gehele getal is ${n}.`,{x})},v=>Math.floor(Math.sqrt(v.x)),true);
richRegister('A4','power-versus-product','Een kwadraat onderscheiden van verdubbelen',2,'rekenmachine','calculation',()=>{const n=randInt(3,12);return richNum(`Iemand voert 2 × ${n} in terwijl ${n}² bedoeld is. Hoeveel is de juiste uitkomst groter?`,n*n-2*n,`${n}² betekent ${n} × ${n} = ${n*n}. Verdubbelen geeft ${2*n}; het verschil is ${n*n-2*n}.`,{n})},v=>v.n*(v.n-2),true);
richRegister('A4','bracket-effect','Het effect van haakjes vergelijken',3,'rekenvolgorde','calculation',()=>{const a=randInt(2,9),b=randInt(2,9),c=randInt(2,6);return richNum(`Hoeveel groter is (${a} + ${b}) × ${c} dan ${a} + ${b} × ${c}?`,a*(c-1),`Met haakjes wordt ook ${a} vermenigvuldigd met ${c}. Zonder haakjes blijft ${a} staan. Het verschil is ${a*c} − ${a} = ${a*(c-1)}.`,{a,b,c})},v=>(v.a+v.b)*v.c-(v.a+v.b*v.c),true);
richRegister('A4','missing-factor','Een ontbrekend getal in een samengestelde berekening',3,'rekenketting','calculation',()=>{const a=randInt(3,8),x=randInt(3,12),b=randInt(2,9),total=a*x+b;return richNum(`Welk getal hoort in □?<br>${a} × □ + ${b} = ${total}`,x,`Haal eerst ${b} van ${total} af. Deel de rest ${a*x} door ${a}: ${x}.`,{a,b,total})},v=>(v.total-v.b)/v.a,true);
richRegister('A4','estimate-check','Een uitkomst op orde van grootte controleren',2,'offerte','offer',()=>{const n=randInt(18,22),p=randInt(48,52),estimate=1000;return richChoice(`${n} tickets kosten € ${p} per stuk. Welke schatting ligt het dichtst bij het totaal?`,'€ 1.000',['€ 100','€ 10.000','€ 100.000'],`Ongeveer 20 × 50 = € 1.000. Het exacte bedrag € ${n*p} ligt daarbij in de buurt.`,{n,p})},v=>['€ 100','€ 1.000','€ 10.000','€ 100.000'].sort((a,b)=>Math.abs(Number(a.replace(/[^0-9]/g,''))-v.n*v.p)-Math.abs(Number(b.replace(/[^0-9]/g,''))-v.n*v.p))[0],true);
richRegister('A4','cube-count','Een kubuslaag vertalen naar een derde macht',3,'bouwblokjes','table',()=>{const n=randInt(3,8);return richNum('Een volle kubus bestaat uit kleine blokjes. Hoeveel kleine blokjes zijn er?',n**3,`Eén laag telt ${n} × ${n} = ${n*n} blokjes. Er zijn ${n} lagen: ${n*n} × ${n} = ${n**3}.`,{n},{visual:richTable('Bouwinstructie',[['Blokjes per rij',n],['Rijen per laag',n],['Aantal lagen',n]])})},v=>Array.from({length:v.n},()=>v.n*v.n).reduce((a,b)=>a+b,0),true);
richRegister('A4','group-division','Eerst een totaal verdelen, daarna aanvullen',3,'groepsbudget','text',()=>{const n=randInt(3,8),share=randInt(8,20),extra=randInt(2,9);return richNum(`Een pot van € ${n*share} wordt gelijk verdeeld over ${n} groepen. Elke groep krijgt daarna nog € ${extra} erbij. Hoeveel krijgt één groep in totaal?`,share+extra,`Deel eerst de pot: ${n*share} : ${n} = € ${share}. Tel daarna de aanvulling op: € ${share+extra}.`,{n,total:n*share,extra},{unit:'€'})},v=>v.total/v.n+v.extra,true);
richRegister('A4','root-first','Een wortel in een samengestelde bewerking',3,'rekenvolgorde','calculation',()=>{const n=randInt(4,12),a=randInt(2,8);return richNum(`Bereken ${a} × √${n*n} + ${n}.`,a*n+n,`Eerst de wortel: √${n*n} = ${n}. Dan vermenigvuldigen en optellen: ${a} × ${n} + ${n} = ${a*n+n}.`,{n,a})},v=>(v.a+1)*Math.sqrt(v.n*v.n),true);
// B1 — deel/geheel, referentie en gelijkwaardigheid.
richRegister('B1','strip-part','Een gekleurde strook als breuk lezen',1,'kleurstrook','strip',()=>{const d=pick([6,8,10,12]),n=randInt(1,d-1);return richNum('Welk deel van de hele strook is gekleurd? Vul een breuk in.',n/d,`Er zijn ${d} even grote vakken; ${n} daarvan zijn gekleurd. Dat is ${n}/${d} = ${reasoningFraction(n,d)}.`,{n,d},{visual:richStrip(n,d),...richFraction(n,d)})},v=>v.n/v.d,true);
richRegister('B1','strip-complement','Het ongekleurde deel herkennen',2,'voortgangsbalk','strip',()=>{const d=pick([6,8,10,12]),n=randInt(1,d-1);return richNum('Welk deel van de balk is nog niet gekleurd? Vul een breuk in.',(d-n)/d,`Van de ${d} vakken zijn er ${n} gekleurd. Er blijven ${d-n} over: ${reasoningFraction(d-n,d)}.`,{n,d},{visual:richStrip(n,d),...richFraction(d-n,d)})},v=>1-v.n/v.d,true);
richRegister('B1','restore-whole','Het geheel uit een zichtbaar deel herstellen',3,'mozaiek','strip',()=>{const parts=pick([3,4,5,6]),n=randInt(2,5),count=parts*n;return richNum(`Deze ${count} steentjes vormen precies ${parts}/${parts+2} van een mozaïek. Hoeveel steentjes heeft het volledige mozaïek?`,(parts+2)*n,`Eén deel bevat ${count} : ${parts} = ${n} steentjes. Het geheel heeft ${parts+2} delen, dus ${(parts+2)*n} steentjes.`,{parts,count})},v=>v.count/v.parts*(v.parts+2),true);
richRegister('B1','same-part-different-whole','Gelijke aantallen tegenover verschillende gehelen',2,'klassen','table',()=>{const n=randInt(4,10),a=3*n,b=4*n;return richChoice('In welke klas is het deel leerlingen dat fietst het grootst?','Klas A.',['Klas B.','Beide even groot.','Niet te bepalen.'],`In beide klassen fietsen ${n} leerlingen. Dat is 1/3 in A en 1/4 in B. Bij hetzelfde aantal is het aandeel groter in de kleinere klas.`,{n,a,b},{visual:reasoningTable(['Klas','Leerlingen','Fietsers'],[['A',a,n],['B',b,n]],'Vervoer naar school')})},v=>v.n/v.a>v.n/v.b?'Klas A.':'Klas B.',true);
richRegister('B1','equivalent-numerator','Een gelijkwaardige breuk aanvullen',2,'breukkaarten','calculation',()=>{const d=pick([3,4,5,6]),n=randInt(1,d-1),k=randInt(2,5);return richNum(`Vul de teller aan: ${n}/${d} = □/${d*k}.`,n*k,`De noemer wordt ${k} keer zo groot. Vermenigvuldig de teller ook met ${k}: ${n*k}.`,{n,d,k})},v=>v.n*(v.d*v.k)/v.d,true);
richRegister('B1','missing-denominator','De noemer van een gelijkwaardige breuk herstellen',2,'breukkaarten','calculation',()=>{const d=pick([3,4,5,7]),n=randInt(1,d-1),k=randInt(2,5);return richNum(`Vul de noemer aan: ${n}/${d} = ${n*k}/□.`,d*k,`De teller is ${k} keer zo groot geworden. De noemer wordt ook ${k} keer zo groot: ${d*k}.`,{n,d,k})},v=>(v.n*v.k)/(v.n/v.d),true);
richRegister('B1','mixed-number','Een breuk groter dan één als gemengd getal lezen',2,'maatbekers','text',()=>{const d=pick([3,4,5,8]),whole=randInt(2,5),r=randInt(1,d-1);return richNum(`Je hebt ${whole*d+r}/${d} liter. Hoeveel hele liters zitten daarin?`,whole,`Elke hele liter bevat ${d}/${d}. Je kunt ${whole} hele liters vormen; daarna blijft ${r}/${d} liter over.`,{d,n:whole*d+r})},v=>Math.floor(v.n/v.d),true);
richRegister('B1','benchmark-half','Hoeveel ontbreekt tot de helft?',3,'vakverdeling','strip',()=>{const d=pick([8,10,12,16]),n=randInt(1,d/2-1);return richNum('Welk deel van de hele strook moet je nog kleuren om precies de helft gekleurd te krijgen?',(d/2-n)/d,`De helft is ${d/2}/${d}. Er is ${n}/${d} gekleurd. Er ontbreekt ${reasoningFraction(d/2-n,d)} van de hele strook.`,{d,n},{visual:richStrip(n,d),...richFraction(d/2-n,d)})},v=>.5-v.n/v.d,true);
richRegister('B1','subdivision','Een deel opnieuw in gelijke stukken verdelen',3,'papierstrook','text',()=>{const d=randInt(3,8),k=randInt(2,5);return richNum(`Een strook is verdeeld in ${d} gelijke delen. Elk deel wordt nog eens in ${k} gelijke stukjes verdeeld. Welk deel van de oorspronkelijke strook is één klein stukje?`,1/(d*k),`Het geheel heeft nu ${d} × ${k} = ${d*k} even grote stukjes. Eén stukje is 1/${d*k}.`,{d,k},{...richFraction(1,d*k)})},v=>1/(v.d*v.k),true);
richRegister('B1','unequal-pieces','Waarom stukjes tellen niet genoeg is',2,'taartverdeling','text',()=>{const correct='Nee, de stukken zijn niet even groot.';return richChoice('Een taart is in vier stukken gesneden die niet even groot zijn. Eén stuk is opgegeten. Is daarmee zeker 1/4 van de taart opgegeten?',correct,['Ja, want één van vier stukken is altijd 1/4.','Nee, er is zeker 3/4 opgegeten.','Ja, zolang de taart rond is.'],'Een breuk als 1/4 verwijst naar vier gelijke delen van het geheel. Alleen het aantal ongelijke stukken vertelt niet hoeveel taart is opgegeten.',{})},()=> 'Nee, de stukken zijn niet even groot.');
// B2 — rekenen met breuken met verschillende relaties.
richRegister('B2','ribbon-join','Ongelijknamige lengtes samenvoegen',2,'linten','table',()=>{const a=randInt(1,3),b=randInt(1,5);return richNum('Hoeveel meter lint is er samen?',a/4+b/6,`Maak twaalfden: ${a}/4 = ${3*a}/12 en ${b}/6 = ${2*b}/12. Samen ${reasoningFraction(3*a+2*b,12)} meter.`,{a,b},{unit:'m',visual:richTable('Lintstukken',[['Rood',`${a}/4 m`],['Blauw',`${b}/6 m`]]),...richFraction(3*a+2*b,12)})},v=>(v.a*3+v.b*2)/12,true);
richRegister('B2','jug-difference','Een tekort tussen breukhoeveelheden',2,'keukenmaat','table',()=>{const d=pick([4,6,8]),need=d+randInt(1,d-1),have=randInt(1,d-1);return richNum('Hoeveel liter moet je nog toevoegen?',(need-have)/d,`Trek de aanwezige hoeveelheid van de benodigde hoeveelheid af: ${need}/${d} − ${have}/${d} = ${reasoningFraction(need-have,d)} liter.`,{d,need,have},{unit:'L',visual:richTable('Recept',[['Nodig',`${need}/${d} L`],['Aanwezig',`${have}/${d} L`]]),...richFraction(need-have,d)})},v=>v.need/v.d-v.have/v.d,true);
richRegister('B2','fraction-portions','Het aantal porties bij een breuk als portiegrootte',3,'soep','label',()=>{const liters=randInt(2,6),den=pick([3,4,5]),num=pick([1,2]);return richNum(`Er is ${liters} liter soep. Eén portie is ${num}/${den} liter. Hoeveel volledige porties kun je maximaal schenken?`,Math.floor(liters*den/num),`Deel de voorraad door de portiegrootte: ${liters} : (${num}/${den}) = ${fmt(liters*den/num)}. Alleen volledige porties tellen.`,{liters,den,num})},v=>{let p=0;while((p+1)*v.num<=v.liters*v.den)p++;return p},true);
richRegister('B2','share-portion','Een breukhoeveelheid gelijk delen',2,'bakactiviteit','text',()=>{const n=randInt(2,5),d=pick([2,3,4]),a=randInt(1,d-1);return richNum(`Je verdeelt ${a}/${d} kg deeg gelijk over ${n} kinderen. Hoeveel kilogram krijgt ieder?`,a/(d*n),`Deel ${a}/${d} door ${n}. Dat is ${a}/(${d} × ${n}) = ${reasoningFraction(a,d*n)} kg.`,{a,d,n},{unit:'kg',...richFraction(a,d*n)})},v=>(v.a/v.d)/v.n,true);
richRegister('B2','part-of-part','Een deel van een deel van een oppervlakte',3,'schooltuin','text',()=>{const a=pick([2,3,4]),b=pick([3,4,5]);return richNum(`Van een tuin is 1/${a} bestemd voor groenten. Van dat groentedeel wordt 1/${b} gebruikt voor wortels. Welk deel van de hele tuin is voor wortels?`,1/(a*b),`Neem 1/${b} van 1/${a}: vermenigvuldig de breuken. Dat is 1/${a*b} van de hele tuin.`,{a,b},{...richFraction(1,a*b)})},v=>1/v.a/v.b,true);
richRegister('B2','remaining-two-parts','Twee delen van hetzelfde geheel aftrekken',3,'dagbesteding','text',()=>{const a=randInt(1,3),b=randInt(1,2);return richNum(`Van een middag besteed je ${a}/8 aan sport en ${b}/8 aan muziek. Deze activiteiten overlappen niet. Welk deel van de middag blijft over?`,(8-a-b)/8,`Beide breuken horen bij dezelfde middag. Trek ze van 8/8 af: (8 − ${a} − ${b})/8 = ${reasoningFraction(8-a-b,8)}.`,{a,b},{...richFraction(8-a-b,8)})},v=>1-v.a/8-v.b/8,true);
richRegister('B2','fraction-equation','Een ontbrekende breukterm herstellen',3,'breukpuzzel','calculation',()=>{const a=randInt(1,3),d=8,b=randInt(5,7);return richNum(`Welke breuk hoort in □?<br>${a}/${d} + □ = ${b}/${d}`, (b-a)/d,`Trek de bekende term af: ${b}/${d} − ${a}/${d} = ${reasoningFraction(b-a,d)}.`,{a,b,d},{...richFraction(b-a,d)})},v=>(v.b-v.a)/v.d,true);
richRegister('B2','recipe-fraction','Een recept met een breukfactor vergroten',3,'receptkaart','recipe',()=>{const d=pick([2,4]),n=pick([3,5]),base=pick([200,400,600]);return richNum(`Je maakt ${n}/${d} keer dit recept. Hoeveel gram meel is nodig?`,base*n/d,`Eén recept vraagt ${base} g. Vermenigvuldig met ${n}/${d}: ${base} : ${d} × ${n} = ${base*n/d} g.`,{d,n,base},{unit:'g',visual:richTable('Eén recept',[['Meel',`${base} g`]])})},v=>v.base*(v.n/v.d),true);
richRegister('B2','whole-from-rest','De oorspronkelijke hoeveelheid uit een rest',3,'wandeling','text',()=>{const d=pick([3,4,5]),part=randInt(3,8),rest=(d-1)*part;return richNum(`Na 1/${d} van een route gelopen te hebben, is er nog ${rest} km over. Hoe lang is de hele route?`,d*part,`De rest is ${d-1}/${d} van de route. Eén deel is ${rest} : ${d-1} = ${part} km. Alle ${d} delen samen zijn ${d*part} km.`,{d,rest},{unit:'km'})},v=>v.rest/(1-1/v.d),true);
richRegister('B2','fraction-product-compare','Het effect van vermenigvuldigen met een breuk',2,'getalredenering','text',()=>{const n=randInt(2,9),d=n+randInt(1,5);return richChoice(`Een positief getal wordt vermenigvuldigd met ${n}/${d}. Wat gebeurt er met het getal?`,'Het wordt kleiner.',['Het wordt groter.','Het blijft gelijk.','Dat hangt van het positieve getal af.'],`${n}/${d} ligt tussen 0 en 1. Je neemt een deel van het positieve getal; de uitkomst is dus kleiner.`,{n,d})},v=>v.n/v.d<1?'Het wordt kleiner.':'Het wordt groter.',true);
// B3 — verschillende schrijfwijzen verbinden aan dezelfde hoeveelheid.
richRegister('B3','percent-strip','Een strook omzetten naar procenten',2,'laadindicator','strip',()=>{const n=randInt(1,9);return richNum('Hoeveel procent van de balk is gekleurd?',10*n,`${n} van de 10 gelijke delen is ${n}/10. Eén deel is 10%, dus ${10*n}%.`,{n},{unit:'%',visual:richStrip(n,10)})},v=>v.n/10*100,true);
richRegister('B3','decimal-strip','Een strook als decimaal schrijven',2,'vulindicator','strip',()=>{const d=pick([4,5,8]),n=randInt(1,d-1);return richNum('Schrijf het gekleurde deel als decimaal getal.',n/d,`Deel de teller door de noemer: ${n} : ${d} = ${fmt(n/d,4)}.`,{n,d},{visual:richStrip(n,d)})},v=>v.n/v.d,true);
richRegister('B3','percent-fraction','Een percentage als breuk geven',2,'deelname','table',()=>{const p=pick([15,25,35,45,60,65,75,80]);return richNum('Welk deel van de deelnemers komt met de fiets? Vul een breuk in.',p/100,`${p}% betekent ${p} van de 100. Vereenvoudig ${p}/100 tot ${reasoningFraction(p,100)}.`,{p},{visual:richTable('Deelname',[['Met de fiets',`${p}%`]]),...richFraction(p,100)})},v=>v.p/100,true);
richRegister('B3','above-one','Meer dan één geheel in procenten',2,'productiedoel','text',()=>{const n=pick([5,6,7,9]),d=4;return richNum(`Een team haalt ${n}/${d} van zijn doel. Hoeveel procent van het doel is dat?`,n/d*100,`Eén geheel is 100%. ${n}/${d} × 100 = ${n/d*100}%. Een resultaat boven 100% is hier mogelijk.`,{n,d},{unit:'%'})},v=>100*v.n/v.d,true);
richRegister('B3','unfilled-percent','Een decimaal gevuld deel aanvullen tot procent',2,'batterij','table',()=>{const p=randInt(15,85);return richNum('Hoeveel procent ontbreekt tot volledig opgeladen?',100-p,`${fmt(p/100)} is ${p}%. Volledig is 100%, dus er ontbreekt ${100-p}%.`,{p},{unit:'%',visual:richTable('Batterijmeting',[['Geladen deel',fmt(p/100)]])})},v=>(1-v.p/100)*100,true);
richRegister('B3','mixed-notation-gap','Verschil tussen twee schrijfwijzen',3,'voortgang','table',()=>{const p=pick([25,50,75]),q=p+randInt(1,4)*5;return richNum('Hoeveel procentpunt is groep B verder dan groep A?',q-p,`Groep A: ${reasoningFraction(p,100)} = ${p}%. Groep B: ${fmt(q/100)} = ${q}%. Verschil: ${q-p} procentpunt.`,{p,q},{unit:'procentpunt',visual:richTable('Voltooid deel',[['Groep A',reasoningFraction(p,100)],['Groep B',fmt(q/100)]])})},v=>v.q-v.p,true);
richRegister('B3','hundredth-error','Een onjuiste procentomzetting herstellen',2,'leerlingnotitie','calculation',()=>{const p=randInt(12,87);return richNum(`Sam schrijft: ${fmt(p/100)} = ${fmt(p/10)}%. Welk percentage hoort werkelijk bij ${fmt(p/100)}?`,p,`Vermenigvuldig het decimale getal met 100, niet met 10: ${fmt(p/100)} × 100 = ${p}%.`,{p},{unit:'%'})},v=>v.p/100*100,true);
richRegister('B3','table-conversion','Een conversietabel aanvullen',2,'omrekentabel','table',()=>{const d=pick([4,5,8,20]),n=randInt(1,d-1);return richNum('Welk percentage hoort in het lege vak?',100*n/d,`De drie kolommen stellen dezelfde verhouding voor. ${n}/${d} × 100 = ${fmt(100*n/d)}%.`,{n,d},{unit:'%',visual:reasoningTable(['Breuk','Decimaal','Percentage'],[[`${n}/${d}`,fmt(n/d,4),'?']],'Drie schrijfwijzen')})},v=>v.n*(100/v.d),true);
richRegister('B3','count-to-decimal','Een telling als decimaal aandeel schrijven',3,'enquete','table',()=>{const total=pick([20,25,40,50]),yes=randInt(1,total-1);return richNum('Schrijf het aandeel ja-antwoorden als decimaal getal.',yes/total,`Het aandeel is aantal ja : totaal = ${yes} : ${total} = ${fmt(yes/total,4)}.`,{yes,total},{visual:richTable('Antwoorden',[['Ja',yes],['Nee',total-yes]])})},v=>v.yes/v.total,true);
richRegister('B3','notation-equality','Een equivalente notatie herkennen',2,'getalkaarten','text',()=>{const p=pick([20,25,40,50,60,75,80]),correct=`${reasoningFraction(p,100)}`;return richChoice(`Welke breuk is precies gelijk aan ${fmt(p/100)}?`,correct,[reasoningFraction(p+5,100),reasoningFraction(p-5,100),reasoningFraction(p,10)],`Schrijf ${fmt(p/100)} als ${p}/100 en vereenvoudig: ${correct}.`,{p})},v=>reasoningFraction(v.p,100),true);
// B4 — procenten met wisselende grondslag, verschil en grenzen.
richRegister('B4','discount-amount','Het kortingsbedrag uit twee prijzen',2,'prijskaart','offer',()=>{const old=randInt(4,12)*20,p=pick([10,15,20,25]),now=old*(1-p/100);return richNum('Hoeveel procent korting is gegeven?',p,`De korting is € ${fmt(old-now)}. Deel door de oude prijs ${old} en vermenigvuldig met 100: ${p}%.`,{old,now},{unit:'%',visual:richTable('Prijskaart',[['Was',`€ ${old}`],['Nu',`€ ${fmt(now)}`]])})},v=>(v.old-v.now)/v.old*100,true);
richRegister('B4','part-total','Het geheel uit een bekend percentage',3,'vereniging','table',()=>{const total=randInt(4,12)*20,p=pick([20,25,40,50]),part=total*p/100;return richNum('Hoeveel leden heeft de vereniging in totaal?',total,`${part} leden vormen ${p}%. Eén procent is ${fmt(part/p)} lid; 100% is ${total} leden.`,{p,part},{visual:richTable('Leden',[['Jeugdleden',part],['Aandeel jeugd',`${p}%`]])})},v=>v.part*100/v.p,true);
richRegister('B4','successive-loss','Het totale verlies na twee dalingen',3,'waterverlies','table',()=>{const p=pick([10,20,25]),q=pick([10,20,40]);return richNum('Hoeveel procent van de oorspronkelijke hoeveelheid gaat in totaal verloren?',100-(100-p)*(100-q)/100,`Na stap 1 blijft ${100-p}% over. Daarvan blijft ${100-q}% over. Samen blijft ${fmt((100-p)*(100-q)/100)}% van het begin over; de rest is verlies.`,{p,q},{unit:'%',visual:richTable('Verlies',[['Eerste stap',`${p}% van het begin`],['Tweede stap',`${q}% van wat dan over is`]])})},v=>100*(1-(1-v.p/100)*(1-v.q/100)));
richRegister('B4','recovery','De benodigde stijging na een daling',4,'bezoekersaantallen','table',()=>{const p=pick([20,50]),start=randInt(3,9)*100,now=start*(1-p/100);return richNum('Met hoeveel procent moet het huidige aantal stijgen om terug te keren naar het oude aantal?',100*p/(100-p),`Er moeten ${start-now} bij, gemeten ten opzichte van het huidige aantal ${now}. Dus ${start-now} : ${now} × 100 = ${100*p/(100-p)}%.`,{start,now},{unit:'%',visual:richTable('Bezoekers',[['Oud',start],['Huidig',now]])})},v=>(v.start/v.now-1)*100);
richRegister('B4','percentage-points','Procentpunten van relatieve groei onderscheiden',3,'opkomst','table',()=>{const a=pick([20,25,40,50]),increase=10;return richNum('Met hoeveel procentpunt is de opkomst gestegen?',increase,`Het verschil tussen percentages is ${a+increase} − ${a} = ${increase} procentpunt. Daarvoor deel je niet door de oude opkomst.`,{a,b:a+increase},{unit:'procentpunt',visual:richTable('Opkomst',[['Vorig jaar',`${a}%`],['Dit jaar',`${a+increase}%`]])})},v=>v.b-v.a,true);
richRegister('B4','vat-extract','Het btw-bedrag uit een prijs inclusief btw',3,'factuur','receipt',()=>{const net=randInt(4,15)*10,p=21,gross=net*1.21;return richNum('Hoeveel euro btw zit in het totaalbedrag?',net*.21,`Het totaal is 121% van de prijs zonder btw. Deel € ${fmt(gross,2)} door 1,21: € ${net}. Het verschil is € ${fmt(net*.21,2)} btw.`,{gross,p},{unit:'€',visual:richTable('Factuur',[['Inclusief btw',`€ ${fmtFixed(gross,2)}`],['Btw over prijs zonder btw','21%']])})},v=>v.gross-v.gross/(1+v.p/100));
richRegister('B4','mixed-groups','Twee groepspercentages met verschillende aantallen combineren',4,'schoolonderzoek','table',()=>{const a=40,b=60,p=pick([25,50,75]),q=pick([20,40,60,80]),yes=a*p/100+b*q/100;return richNum('Hoeveel procent van beide groepen samen kiest voor sport?',yes,`Bereken aantallen: ${a} × ${p}% = ${a*p/100}; ${b} × ${q}% = ${b*q/100}. Samen ${yes} van 100, dus ${yes}%.`,{a,b,p,q},{unit:'%',visual:reasoningTable(['Groep','Aantal','Sport'],[['A',a,`${p}%`],['B',b,`${q}%`]],'Keuzes')})},v=>(v.a*v.p+v.b*v.q)/(v.a+v.b));
richRegister('B4','discount-limit','De hoogste prijs vóór korting binnen een budget',3,'winkelbudget','offer',()=>{const old=randInt(8,20)*10,p=pick([20,25,50]),budget=old*(1-p/100);return richNum(`Er geldt ${p}% korting op alle artikelen. Je kunt maximaal € ${fmt(budget)} betalen. Wat is de hoogste oorspronkelijke prijs die binnen je budget past?`,old,`Je betaalt ${100-p}% van de oorspronkelijke prijs. Deel het budget door ${fmt(1-p/100)}: € ${old}.`,{p,budget},{unit:'€'})},v=>v.budget*100/(100-v.p),true);
richRegister('B4','extra-content','Extra inhoud vergelijken met gewone inhoud',3,'verpakking','label',()=>{const base=pick([200,400,500]),extra=pick([10,20,25]),now=base*(1+extra/100);return richNum('Hoeveel procent extra inhoud bevat de actievariant?',extra,`Er is ${now-base} ml extra. Vergelijk dat met de gewone ${base} ml: ${now-base} : ${base} × 100 = ${extra}%.`,{base,now},{unit:'%',visual:richTable('Verpakkingen',[['Gewoon',`${base} ml`],['Actie',`${now} ml`]])})},v=>(v.now/v.base-1)*100,true);
richRegister('B4','rejected-production','Goedgekeurde aantallen uit een afkeurpercentage',2,'productiecontrole','table',()=>{const total=randInt(4,15)*100,p=pick([2,4,5,8]);return richNum('Hoeveel producten zijn goedgekeurd? Alles wat niet is afgekeurd, is goedgekeurd.',total*(100-p)/100,`Goedgekeurd is 100% − ${p}% = ${100-p}%. Neem dit deel van ${total}: ${total*(100-p)/100}.`,{total,p},{visual:richTable('Controle',[['Gecontroleerd',total],['Afgekeurd',`${p}%`]])})},v=>v.total-v.total*v.p/100,true);
// B5 — evenredigheid, schaal, mengsels en kans.
richRegister('B5','recipe-scale','Een recept naar een ander aantal personen schalen',2,'recept','recipe',()=>{const per=randInt(20,50)*5,a=pick([3,4,6]),b=pick([5,7,8]);return richNum(`Dit recept is voor ${a} personen. Hoeveel gram rijst is nodig voor ${b} personen?`,per*b,`Reken eerst terug naar één persoon: ${a*per} : ${a} = ${per} g. Voor ${b} personen is dat ${per*b} g.`,{a,b,amount:a*per},{unit:'g',visual:richTable('Receptkaart',[['Personen',a],['Rijst',`${a*per} g`]])})},v=>v.amount*v.b/v.a,true);
richRegister('B5','ratio-total','Een totaal verdelen volgens een verhouding',3,'verf-mengen','table',()=>{const a=pick([2,3]),b=pick([4,5]),unit=randInt(2,8)*10;return richNum('Hoeveel milliliter blauwe verf is nodig?',b*unit,`De verhouding heeft ${a+b} delen. Eén deel is ${(a+b)*unit} : ${a+b} = ${unit} ml. Blauw krijgt ${b} delen: ${b*unit} ml.`,{a,b,total:(a+b)*unit},{unit:'ml',visual:richTable('Mengplan',[['Wit : blauw',`${a} : ${b}`],['Totale hoeveelheid',`${(a+b)*unit} ml`]])})},v=>v.total/(v.a+v.b)*v.b,true);
richRegister('B5','limiting-ingredient','Het beperkende ingrediënt bepalen',3,'bakken','recipe',()=>{const per=pick([50,100]),flour=per*randInt(4,8),eggs=randInt(2,3);return richNum('Hoeveel volledige cakes kun je maximaal maken?',eggs,`Met het meel kan je ${flour/per} cakes maken, maar met de eieren slechts ${eggs}. Het kleinste aantal begrenst de productie.`,{per,flour,eggs},{visual:reasoningTable(['Ingrediënt','Per cake','Voorraad'],[['Meel',`${per} g`,`${flour} g`],['Eieren','1',eggs]],'Voorraad')})},v=>Math.min(Math.floor(v.flour/v.per),v.eggs));
richRegister('B5','map-distance','Een kaartafstand in werkelijkheid berekenen',2,'wandelkaart','scale',()=>{const scale=pick([10000,20000,25000]),cm=randInt(2,8);return richNum(`Op een kaart met schaal 1 : ${scale} is een route ${cm} cm lang. Hoeveel kilometer is dat in werkelijkheid?`,cm*scale/100000,`Eén cm op de kaart is ${scale} cm buiten. Vermenigvuldig met ${cm} en deel door 100.000 voor kilometers.`,{scale,cm},{unit:'km'})},v=>v.cm*(v.scale/100)/1000,true);
richRegister('B5','promille','Promille toepassen op een grote groep',2,'kwaliteitsmeting','label',()=>{const p=randInt(2,8),total=randInt(3,9)*1000;return richNum(`${p}‰ van ${total} metingen wijkt af. Hoeveel metingen zijn dat?`,p*total/1000,`Promille betekent per duizend. ${total} bevat ${total/1000} groepen van duizend; ${p} × ${total/1000} = ${p*total/1000}.`,{p,total})},v=>v.total*(v.p/1000),true);
richRegister('B5','complement-probability','De kans op niet-rood uit aantallen',2,'grabbelzak','table',()=>{const red=randInt(2,6),blue=randInt(2,6),green=randInt(2,6),total=red+blue+green;return richNum('Je trekt blind één bal. Elke bal heeft evenveel kans. Wat is de kans dat de bal niet rood is? Geef een breuk.',(blue+green)/total,`Niet rood zijn de ${blue} blauwe en ${green} groene ballen: ${blue+green} van ${total}.`,{red,blue,green},{visual:richTable('Ballen',[['Rood',red],['Blauw',blue],['Groen',green]]),...richFraction(blue+green,total)})},v=>1-v.red/(v.red+v.blue+v.green),true);
richRegister('B5','without-replacement','Een trekkans na wegnemen herberekenen',3,'loten','table',()=>{const win=randInt(3,6),blank=randInt(5,9),total=win+blank;return richNum('Een prijswinnend lot is getrokken en niet teruggelegd. Wat is de kans dat het volgende blind getrokken lot ook prijs heeft? Elk overgebleven lot heeft evenveel kans.',(win-1)/(total-1),`Er blijft één prijs minder én één lot minder over. De kans wordt ${win-1}/${total-1}.`,{win,blank},{visual:richTable('Vóór de eerste trekking',[['Prijs',win],['Geen prijs',blank]]),...richFraction(win-1,total-1)})},v=>(v.win-1)/(v.win+v.blank-1));
richRegister('B5','two-independent','Onafhankelijke kansen combineren',3,'draaischijven','text',()=>{const a=pick([3,4,5]),b=pick([4,5,6]);return richNum(`Schijf A heeft ${a} even grote vakken, waarvan één rood. Schijf B heeft ${b} even grote vakken, waarvan één rood. Je draait beide onafhankelijk. Wat is de kans op twee keer rood?`,1/(a*b),`De kans is 1/${a} × 1/${b} = 1/${a*b}. Elke combinatie van twee vakken is even waarschijnlijk.`,{a,b},{...richFraction(1,a*b)})},v=>1/(v.a*v.b));
richRegister('B5','ratio-repair','Een mengverhouding herstellen door toevoegen',4,'limonade','table',()=>{const syrup=randInt(2,6)*100,ratio=pick([4,5,6]),missing=randInt(1,3)*100,water=syrup*ratio-missing;return richNum('Hoeveel ml water moet erbij om de gewenste verhouding te krijgen? Er wordt niets weggegooid.',missing,`Bij ${syrup} ml siroop hoort ${ratio} × ${syrup} = ${syrup*ratio} ml water. Aanwezig is ${water}, dus voeg ${missing} ml toe.`,{syrup,ratio,water},{unit:'ml',visual:richTable('Mengsel',[['Gewenst siroop : water',`1 : ${ratio}`],['Siroop aanwezig',`${syrup} ml`],['Water aanwezig',`${water} ml`]])})},v=>v.syrup*v.ratio-v.water);
richRegister('B5','inverse-workers','Tijd bij evenredig meer werkers',3,'samenwerken','table',()=>{const workers=pick([2,3,4]),hours=pick([6,8,10]),factor=2;return richNum('Hoeveel uur duurt hetzelfde werk met twee keer zoveel mensen? Iedereen werkt even snel; er is geen extra overleg of wachttijd.',hours/2,`De totale hoeveelheid werk blijft ${workers*hours} arbeidsuren. Met ${2*workers} mensen duurt het ${hours/2} uur.`,{workers,hours},{unit:'uur',visual:richTable('Oorspronkelijk plan',[['Mensen',workers],['Tijdsduur',`${hours} uur`]])})},v=>(v.workers*v.hours)/(2*v.workers),true);
// C1 — eenheden, schaalstappen en samengestelde registraties.
richRegister('C1','mixed-length','Meters en centimeters samenvoegen',2,'rolmaat','label',()=>{const m=randInt(2,8),cm=randInt(10,90);return richNum(`Een lengte is ${m} m en ${cm} cm. Hoeveel centimeter is dit samen?`,100*m+cm,`${m} m is ${100*m} cm. Tel ${cm} cm erbij: ${100*m+cm} cm.`,{m,cm},{unit:'cm'})},v=>v.m*100+v.cm,true);
richRegister('C1','weight-remainder','Gewichten met verschillende eenheden vergelijken',2,'bagage','label',()=>{const limit=randInt(8,15),grams=randInt(2,7)*100,current=limit*1000-grams;return richNum(`De bagagelimiet is ${limit} kg. Je tas weegt ${current} g. Hoeveel gram kan er nog bij?`,grams,`Zet de limiet om: ${limit} kg = ${limit*1000} g. Trek ${current} g af.`,{limit,current},{unit:'g'})},v=>v.limit*1000-v.current,true);
richRegister('C1','liters-milliliters','Liters en milliliters combineren',2,'drankvoorraad','table',()=>{const liters=randInt(2,6),bottles=randInt(3,7),ml=250;return richNum('Hoeveel liter drank is er samen?',liters+bottles/4,`${bottles} flessen van 250 ml is ${bottles*250} ml = ${fmt(bottles/4)} L. Tel ${liters} L erbij.`,{liters,bottles,ml},{unit:'L',visual:richTable('Voorraad',[['Kan',`${liters} L`],['Flesjes',`${bottles} × ${ml} ml`]])})},v=>(v.liters*1000+v.bottles*v.ml)/1000,true);
richRegister('C1','area-to-cm','Vierkante meters naar vierkante centimeters',2,'vloeroppervlak','text',()=>{const a=randInt(2,9)/2;return richNum(`Hoeveel cm² is ${fmt(a)} m²?`,a*10000,`Eén m² is 100 cm × 100 cm = 10.000 cm². Vermenigvuldig ${fmt(a)} dus met 10.000.`,{a},{unit:'cm²'})},v=>(v.a*100)*100,true);
richRegister('C1','cubic-to-liters','Kubieke decimeters aan liters koppelen',2,'opslagvat','label',()=>{const dm=randInt(12,95);return richNum(`Op een vat staat ${dm} dm³. Hoeveel liter is dat?`,dm,'Eén dm³ is precies één liter. Het getal blijft daarom gelijk.',{dm},{unit:'L'})},v=>v.dm,true);
richRegister('C1','hectare','Hectares naar vierkante meters omrekenen',2,'landbouw','label',()=>{const a=randInt(2,25)/10;return richNum(`Een perceel is ${fmt(a)} hectare. Hoeveel vierkante meter is dat?`,a*10000,`Een hectare is 100 m × 100 m = 10.000 m². Dus ${fmt(a)} × 10.000 = ${a*10000} m².`,{a},{unit:'m²'})},v=>v.a*100*100,true);
richRegister('C1','time-seconds','Een samengestelde tijd naar seconden',2,'sporttijd','label',()=>{const minutes=randInt(2,9),seconds=randInt(10,59);return richNum(`Een rondetijd is ${minutes} minuten en ${seconds} seconden. Hoeveel seconden is dat?`,minutes*60+seconds,`Elke minuut telt 60 seconden. ${minutes} × 60 + ${seconds} = ${minutes*60+seconds}.`,{minutes,seconds},{unit:'s'})},v=>v.minutes*60+v.seconds,true);
richRegister('C1','mass-packs','Verschillende verpakkingsgewichten samen optellen',3,'inkoop','table',()=>{const n=randInt(3,8),big=randInt(1,4);return richNum('Hoeveel kilogram is de totale voorraad?',n*.25+big,`${n} × 250 g = ${n*250} g. Voeg ${big*1000} g toe en deel het totaal door 1.000.`,{n,big},{unit:'kg',visual:richTable('Verpakkingen',[['Klein',`${n} × 250 g`],['Groot',`${big} × 1 kg`]])})},v=>(v.n*250+v.big*1000)/1000,true);
richRegister('C1','unit-dimension','De passende oppervlakte-eenheid kiezen',2,'meetrapport','text',()=>richChoice('Je berekent hoeveel verf nodig is voor het vlak van een muur. Welke eenheid past bij de grootte van dat vlak?','m²',['m','m³','kg'],'Het gaat om een oppervlakte: lengte maal hoogte. Die wordt uitgedrukt in vierkante meters.',{}),()=> 'm²');
richRegister('C1','cubic-meter-fill','Een reservoirinhoud naar kleine flessen vertalen',3,'watervoorraad','table',()=>{const cubic=randInt(2,8)/10,ml=500;return richNum('Hoeveel volle flessen kun je vullen? Er gaat geen water verloren.',cubic*2000,`${fmt(cubic)} m³ is ${cubic*1000} L. Een fles is 0,5 L. Deel door 0,5: ${cubic*2000} flessen.`,{cubic,ml},{visual:richTable('Water',[['Reservoir',`${fmt(cubic)} m³`],['Fles',`${ml} ml`]])})},v=>v.cubic*1000000/v.ml);
function richTriangle(base,height){return reasoningSvg(`<path d="M60 170 L390 170 L175 45 Z" fill="#eaf6ff" stroke="#123b5d" stroke-width="3"/><path d="M175 45 V170" stroke="#24846b" stroke-width="3" stroke-dasharray="5 4"/><path d="M175 155 H190 V170" fill="none" stroke="#24846b"/><text x="225" y="205" font-size="20">${base} cm</text><text x="190" y="108" font-size="20">${height} cm</text>`,`Driehoek: basis ${base} cm en loodrechte hoogte ${height} cm. Schematisch, niet op schaal.`,230)}
function richCircle(radius){return reasoningSvg(`<circle cx="230" cy="110" r="80" fill="#eaf6ff" stroke="#123b5d" stroke-width="3"/><line x1="230" y1="110" x2="310" y2="110" stroke="#24846b" stroke-width="3"/><circle cx="230" cy="110" r="4" fill="#123b5d"/><text x="238" y="100" font-size="20">${radius} cm</text>`,`Cirkel met straal ${radius} centimeter, van middelpunt tot rand.`,225)}
// C2 — rand, vlak, uitsparingen en omgekeerde gegevens.
richRegister('C2','gate-perimeter','Heklengte met een poortopening',2,'tuin','diagram',()=>{const l=randInt(8,16),w=randInt(4,7),gate=pick([2,3]);return richNum(`Om deze rechthoekige tuin komt een hek, behalve bij een poortopening van ${gate} m. Hoeveel meter hek is nodig?`,2*(l+w)-gate,`De omtrek is 2 × (${l} + ${w}) = ${2*(l+w)} m. Trek de poortopening af: ${2*(l+w)-gate} m.`,{l,w,gate},{unit:'m',visual:richRect(l,w)})},v=>v.l+v.w+v.l+v.w-v.gate,true);
richRegister('C2','triangle-inverse','Een driehoeksbasis uit oppervlakte en hoogte',3,'zeildoek','diagram',()=>{const b=randInt(4,12)*2,h=randInt(3,9),area=b*h/2;return richNum(`Dit driehoekige zeil heeft oppervlakte ${area} cm². De loodrechte hoogte is ${h} cm. Hoe lang is de basis?`,b,`Een driehoek heeft oppervlakte basis × hoogte : 2. Verdubbel ${area} en deel door ${h}: ${b} cm.`,{area,h},{unit:'cm',visual:richTriangle('?',h)})},v=>2*v.area/v.h);
richRegister('C2','triangle-area','Een loodrechte hoogte gebruiken',2,'vlag','diagram',()=>{const b=randInt(3,9)*2,h=randInt(3,10);return richNum('Hoeveel cm² stof is nodig voor deze driehoekige vlag? Reken zonder naden.',b*h/2,`Neem de basis en de loodrechte hoogte: ${b} × ${h} : 2 = ${b*h/2} cm².`,{b,h},{unit:'cm²',visual:richTriangle(b,h)})},v=>v.b*(v.h/2),true);
richRegister('C2','cutout','Een rechthoekige uitsparing van een vlak aftrekken',3,'wand','diagram',()=>{const l=randInt(6,12),h=randInt(3,5),hole=2;return richNum(`De wand heeft één raam van 2 m bij 1 m. Hoeveel m² wand blijft over om te schilderen?`,l*h-hole,`De hele wand is ${l} × ${h} = ${l*h} m². Het raam is 2 m². Trek dat af: ${l*h-hole} m².`,{l,h,hole},{unit:'m²',visual:richRect(l,h,'m','Wand; raam niet ingetekend')})},v=>v.l*v.h-v.hole,true);
richRegister('C2','rectangle-width','Een ontbrekende maat uit de omtrek',3,'fotolijst','diagram',()=>{const l=randInt(12,24),w=randInt(5,10),p=2*(l+w);return richNum(`De omtrek van de rechthoek is ${p} cm. Hoe breed is de rechthoek?`,w,`De halve omtrek is lengte + breedte: ${p} : 2 = ${l+w}. Trek de lengte ${l} af: ${w} cm.`,{l,p},{unit:'cm',visual:richRect(l,'?','cm')})},v=>(v.p-2*v.l)/2,true);
richRegister('C2','parallelogram','Een scheve rand onderscheiden van de hoogte',3,'parallellogram','diagram',()=>{const b=randInt(5,12),h=randInt(3,7),side=h+2;const visual=reasoningSvg(`<path d="M50 175 L330 175 L410 50 L130 50 Z" fill="#eaf6ff" stroke="#123b5d" stroke-width="3"/><path d="M130 50 V175" stroke="#24846b" stroke-width="3" stroke-dasharray="5 4"/><text x="185" y="205" font-size="20">${b} cm</text><text x="145" y="110" font-size="20">${h} cm</text><text x="35" y="105" font-size="20">${side} cm</text>`,`Parallellogram met basis ${b} cm, loodrechte hoogte ${h} cm en schuine zijde ${side} cm. Schematisch.`,230);return richNum('Wat is de oppervlakte van dit parallellogram?',b*h,`Gebruik de loodrechte hoogte ${h}, niet de schuine zijde ${side}: ${b} × ${h} = ${b*h} cm².`,{b,h,side},{unit:'cm²',visual})},v=>v.b*v.h);
richRegister('C2','circle-circumference','Een rand uit de straal berekenen',3,'ronde-tafel','diagram',()=>{const r=randInt(3,10);return richNum('Bereken de omtrek. Gebruik π = 3,14.',2*3.14*r,`De diameter is 2 × ${r} = ${2*r} cm. Omtrek = π × diameter = 3,14 × ${2*r} = ${fmt(2*3.14*r,2)} cm.`,{r},{unit:'cm',visual:richCircle(r),calculatorAllowed:true})},v=>3.14*(v.r+v.r));
richRegister('C2','circle-area','Een cirkeloppervlakte uit de straal',3,'rond-deksel','diagram',()=>{const r=randInt(3,10);return richNum('Bereken de oppervlakte. Gebruik π = 3,14.',3.14*r*r,`Oppervlakte = π × straal² = 3,14 × ${r} × ${r} = ${fmt(3.14*r*r,2)} cm².`,{r},{unit:'cm²',visual:richCircle(r),calculatorAllowed:true})},v=>3.14*v.r**2);
richRegister('C2','l-shape','Een L-vorm uit twee niet-overlappende rechthoeken',3,'terras','table',()=>{const a=randInt(6,10),b=randInt(3,5),c=randInt(2,5),d=randInt(2,4);return richNum('Het terras bestaat uit twee rechthoeken die elkaar niet overlappen. Wat is de totale oppervlakte?',a*b+c*d,`Bereken beide vlakken apart: ${a} × ${b} = ${a*b} en ${c} × ${d} = ${c*d}. Tel de oppervlakten op.`,{a,b,c,d},{unit:'m²',visual:reasoningTable(['Deel','Lengte','Breedte'],[['1',`${a} m`,`${b} m`],['2',`${c} m`,`${d} m`]],'Terrasdelen')})},v=>v.a*v.b+v.c*v.d);
richRegister('C2','scale-area-effect','Het effect van één gewijzigde afmeting',3,'vloerkleed','text',()=>{const l=randInt(4,10),w=randInt(3,6),extra=randInt(1,4);return richNum(`Een rechthoek van ${l} bij ${w} m wordt alleen in de lengte ${extra} m groter. Hoeveel m² komt erbij?`,extra*w,`De extra strook is ${extra} m lang en ${w} m breed. Er komt ${extra} × ${w} = ${extra*w} m² bij.`,{l,w,extra},{unit:'m²'})},v=>(v.l+v.extra)*v.w-v.l*v.w,true);
// C3 — inhoud, buitenoppervlak, lagen en verpakkingen.
richRegister('C3','aquarium','Waterinhoud met een ongevulde bovenrand',3,'aquarium','table',()=>{const l=pick([40,50,60]),w=pick([20,30]),h=pick([30,40]),empty=5;return richNum('Hoeveel liter water bevat het aquarium? Gebruik de binnenmaten.',l*w*(h-empty)/1000,`De waterhoogte is ${h} − ${empty} = ${h-empty} cm. Vermenigvuldig de drie maten en deel cm³ door 1.000 voor liters.`,{l,w,h,empty},{unit:'L',visual:richTable('Binnenmaten',[['Lengte',`${l} cm`],['Breedte',`${w} cm`],['Hoogte',`${h} cm`],['Ongevulde bovenrand',`${empty} cm`]])})},v=>v.l*v.w*v.h/1000-v.l*v.w*v.empty/1000);
richRegister('C3','box-height','Hoogte uit inhoud en grondvlak',3,'doos','table',()=>{const l=randInt(3,8),w=randInt(2,5),h=randInt(2,9);return richNum('Hoe hoog is de doos?',h,`Het grondvlak is ${l} × ${w} = ${l*w} cm². Deel de inhoud ${l*w*h} cm³ door dat grondvlak: ${h} cm.`,{l,w,volume:l*w*h},{unit:'cm',visual:richTable('Doos',[['Lengte',`${l} cm`],['Breedte',`${w} cm`],['Inhoud',`${l*w*h} cm³`]])})},v=>v.volume/(v.l*v.w),true);
richRegister('C3','cube-surface','De buitenkant van een kubus',2,'cadeaudoos','text',()=>{const edge=randInt(3,12);return richNum(`Een gesloten kubus heeft ribben van ${edge} cm. Wat is de totale buitenoppervlakte?`,6*edge*edge,`Er zijn zes vierkante vlakken, ieder ${edge} × ${edge} = ${edge*edge} cm². Samen ${6*edge*edge} cm².`,{edge},{unit:'cm²'})},v=>Array(6).fill(v.edge**2).reduce((a,b)=>a+b,0),true);
richRegister('C3','open-box','Oppervlakte van een open bak',3,'opbergbak','table',()=>{const l=randInt(5,10),w=randInt(3,6),h=randInt(2,5);return richNum('De bak heeft een bodem en vier zijwanden, maar geen deksel. Hoeveel cm² materiaal is nodig? Negeer materiaaldikte en naden.',l*w+2*l*h+2*w*h,`Tel de bodem en vier wanden: ${l*w} + 2 × ${l*h} + 2 × ${w*h} = ${l*w+2*l*h+2*w*h} cm².`,{l,w,h},{unit:'cm²',visual:richTable('Maten',[['Lengte',`${l} cm`],['Breedte',`${w} cm`],['Hoogte',`${h} cm`]])})},v=>v.l*v.w+2*v.h*(v.l+v.w));
richRegister('C3','cube-removal','Een hoekblokje uit een vol bouwsel wegnemen',2,'blokjesbouwsel','text',()=>{const n=randInt(3,6);return richNum(`Een volle kubus bestaat uit ${n} × ${n} × ${n} kleine blokjes. Eén hoekblokje wordt weggehaald. Hoeveel blokjes blijven over?`,n**3-1,`Het volle bouwsel telt ${n**3} blokjes. Na het weghalen blijft ${n**3-1} over.`,{n})},v=>v.n*v.n*v.n-1,true);
richRegister('C3','layer-count','Volledige lagen in een opslagruimte',3,'magazijn','table',()=>{const l=randInt(3,6)*10,w=randInt(2,5)*10,h=randInt(2,4)*10+5,edge=10;return richNum('Hoeveel kubusdozen van 10 × 10 × 10 cm passen in rechte rijen en volledige lagen? Gebruik de binnenmaten.',l/10*w/10*Math.floor(h/10),`Per laag passen ${l/10} × ${w/10} dozen. In de hoogte passen ${Math.floor(h/10)} volledige lagen; de overige 5 cm is te weinig voor een extra laag.`,{l,w,h},{visual:richTable('Opslagruimte',[['Lengte',`${l} cm`],['Breedte',`${w} cm`],['Hoogte',`${h} cm`]])})},v=>Math.floor(v.l/10)*Math.floor(v.w/10)*Math.floor(v.h/10));
richRegister('C3','displacement','Waterstijging door een ondergedompeld voorwerp',3,'proefopstelling','table',()=>{const l=randInt(4,10),w=randInt(3,7),rise=randInt(2,5);return richNum('Een voorwerp wordt volledig ondergedompeld. Er stroomt geen water over. Wat is het volume van het voorwerp?',l*w*rise,`Het voorwerp verdringt een waterlaag van ${rise} cm hoog over het grondvlak ${l*w} cm². Volume = ${l*w*rise} cm³.`,{l,w,rise},{unit:'cm³',visual:richTable('Rechthoekige bak',[['Binnenlengte',`${l} cm`],['Binnenbreedte',`${w} cm`],['Waterstijging',`${rise} cm`]])})},v=>(v.l*v.w)*v.rise);
richRegister('C3','cylinder','Inhoud van een cilinder met gegeven straal',3,'cilindervat','table',()=>{const r=randInt(2,6),h=randInt(5,12);return richNum('Bereken de inhoud van deze cilinder. Gebruik π = 3,14.',3.14*r*r*h,`Het grondvlak is 3,14 × ${r}² cm². Vermenigvuldig met hoogte ${h}: ${fmt(3.14*r*r*h,2)} cm³.`,{r,h},{unit:'cm³',calculatorAllowed:true,visual:richTable('Binnenmaten cilinder',[['Straal',`${r} cm`],['Hoogte',`${h} cm`]])})},v=>3.14*v.h*v.r**2);
richRegister('C3','double-dimensions','Inhoudsverandering bij drie vergrote maten',3,'schaalmodel','text',()=>{const k=pick([2,3,4]);return richNum(`Van een balk worden lengte, breedte én hoogte ${k} keer zo groot. Hoeveel keer zo groot wordt de inhoud?`,k**3,`Elke richting draagt een factor ${k} bij. Samen: ${k} × ${k} × ${k} = ${k**3}.`,{k},{unit:'keer'})},v=>v.k**3,true);
richRegister('C3','joined-cubes','Buitenoppervlak van twee samengevoegde kubussen',4,'blokconstructie','text',()=>{const a=randInt(2,8);return richNum(`Twee gelijke kubussen met ribbe ${a} cm worden met één heel zijvlak tegen elkaar geplakt. Wat is de buitenoppervlakte van het nieuwe blok?`,10*a*a,`Samen hebben ze 12 vlakken. De twee tegen elkaar geplakte vlakken liggen binnenin. Er blijven 10 zichtbare vlakken van ${a*a} cm² over.`,{a},{unit:'cm²'})},v=>2*((2*v.a)*v.a+(2*v.a)*v.a+v.a*v.a));
// C4 — tijd, snelheid en samengestelde grootheden.
richRegister('C4','departure','Terugplannen vanaf een aankomsttijd',3,'busreis','timetable',()=>{const arrival=randInt(9,15)*60,travel=randInt(3,8)*5,walk=10;return richNum(`Je moet om ${richClock(arrival)} aankomen. Hoeveel minuten vóór dat tijdstip moet je uiterlijk van huis vertrekken? De reistijden sluiten op elkaar aan zonder wachttijd.`,travel+walk,`Tel de busrit en de wandeling op: ${travel} + ${walk} = ${travel+walk} minuten vóór de afspraak.`,{travel,walk},{unit:'min',visual:richTable('Reis',[['Lopen naar de halte',`${walk} min`],['Busrit',`${travel} min`]])})},v=>v.travel+v.walk,true);
richRegister('C4','midnight','Een tijdsduur over middernacht',2,'nachttrein','timeline',()=>{const a=randInt(2,5)*5,b=randInt(3,9)*5;return richNum('Hoeveel minuten duurt deze rit?',a+b,`Tot middernacht is ${a} minuten. Na middernacht volgen ${b} minuten. Samen ${a+b}.`,{a,b},{unit:'min',visual:richTimeline([richClock(1440-a),'00.00',richClock(b)])})},v=>(1440+v.b)-(1440-v.a),true);
richRegister('C4','speed-distance','Afstand uit snelheid en minuten',2,'fietsen','table',()=>{const speed=pick([12,18,24]),minutes=pick([10,20,30,40]);return richNum('Hoeveel kilometer leg je af bij een constante snelheid?',speed*minutes/60,`${minutes} minuten is ${minutes}/60 uur. Afstand = ${speed} × ${minutes}/60 = ${fmt(speed*minutes/60)} km.`,{speed,minutes},{unit:'km',visual:richTable('Rit',[['Snelheid',`${speed} km/u`],['Duur',`${minutes} minuten`]])})},v=>v.speed/60*v.minutes,true);
richRegister('C4','mean-trip','Gemiddelde snelheid inclusief pauze',3,'wandeltocht','table',()=>{const distance=randInt(6,12),walk=120,pause=30;return richNum('Wat is de gemiddelde snelheid over de hele tocht, inclusief pauze?',distance/2.5,`De totale tijd is 150 minuten = 2,5 uur. Deel de volledige afstand door de volledige tijd.`,{distance,walk,pause},{unit:'km/u',visual:richTable('Tocht',[['Afstand',`${distance} km`],['Lopen',`${walk} min`],['Pauze',`${pause} min`]])})},v=>v.distance*60/(v.walk+v.pause));
richRegister('C4','speed-conversion','Meters per seconde naar kilometer per uur',2,'snelheidsmeter','label',()=>{const speed=randInt(3,12);return richNum(`Hoeveel km/u is ${speed} m/s?`,speed*3.6,`In een uur zijn 3.600 seconden. ${speed} × 3.600 meter is ${speed*3.6} kilometer.`,{speed},{unit:'km/u'})},v=>v.speed*3600/1000,true);
richRegister('C4','density','Massa bij een gegeven massa per volume',3,'materiaalkaart','label',()=>{const density=pick([2,3,4]),volume=randInt(20,80);return richNum('Wat is de massa van het materiaal?',density*volume,`Elke cm³ weegt ${density} gram. Vermenigvuldig met ${volume} cm³: ${density*volume} g.`,{density,volume},{unit:'g',visual:richTable('Materiaal',[['Massa per cm³',`${density} g`],['Volume',`${volume} cm³`]])})},v=>v.volume*v.density,true);
richRegister('C4','production-time','Productietijd uit een tempo',3,'printer','label',()=>{const rate=randInt(4,10),minutes=randInt(6,18),pages=rate*minutes;return richNum(`Een printer drukt ${rate} pagina’s per minuut. Hoeveel minuten duren ${pages} pagina’s? Start- en wachttijd tellen niet mee.`,minutes,`Deel de benodigde pagina’s door het aantal per minuut: ${pages} : ${rate} = ${minutes}.`,{rate,pages},{unit:'min'})},v=>v.pages/v.rate,true);
richRegister('C4','consumption','Brandstof uit een verbruik per afstand',3,'autoreis','table',()=>{const per100=pick([5,6,8]),distance=randInt(2,8)*50;return richNum('Hoeveel liter brandstof is nodig bij dit constante verbruik?',per100*distance/100,`De afstand is ${fmt(distance/100)} keer 100 km. Vermenigvuldig dit met ${per100} liter.`,{per100,distance},{unit:'L',visual:richTable('Rit',[['Verbruik',`${per100} L per 100 km`],['Afstand',`${distance} km`]])})},v=>v.distance*(v.per100/100),true);
richRegister('C4','catch-up','Een achterstand met een snelheidsverschil inlopen',4,'fietstocht','table',()=>{const gap=pick([3,6,9]),slow=12,fast=18;return richNum('Beide fietsers rijden dezelfde kant op en behouden hun snelheid. Na hoeveel minuten haalt B fietser A in?',gap/6*60,`B loopt ${fast-slow} km per uur in. Voor ${gap} km is ${fmt(gap/(fast-slow))} uur nodig; dat is ${gap/6*60} minuten.`,{gap,slow,fast},{unit:'min',visual:richTable('Startsituatie',[['A voor op B',`${gap} km`],['Snelheid A',`${slow} km/u`],['Snelheid B',`${fast} km/u`]])})},v=>v.gap/(v.fast-v.slow)*60);
richRegister('C4','transfer','Een overstap na vertraging beoordelen',3,'treinreis','timetable',()=>{const arrival=600+randInt(1,5)*5,wait=randInt(8,15),delay=randInt(2,5),walk=3;return richNum('Hoeveel minuten speling blijven na het lopen naar het vertrekperron? De volgende trein vertrekt op tijd.',wait-delay-walk,`De vertraagde aankomst is ${richClock(arrival+delay)}. Tot vertrek blijven ${wait-delay} minuten. Trek ${walk} minuten lopen af.`,{wait,delay,walk},{unit:'min',visual:richTable('Overstap',[['Aankomst gepland',richClock(arrival)],['Vertraging',`${delay} min`],['Volgende trein',richClock(arrival+wait)],['Lopen',`${walk} min`]])})},v=>v.wait-(v.delay+v.walk));
// C5 — schaal, hoek, coördinaat en ruimtelijke relaties.
function richGridPoint(x,y){let b='';for(let i=0;i<=6;i++)b+=`<path d="M${60+i*50} 25 V325 M60 ${325-i*50} H360" stroke="#c4d3dd"/><text x="${60+i*50}" y="350" text-anchor="middle" font-size="17">${i}</text><text x="40" y="${331-i*50}" text-anchor="middle" font-size="17">${i}</text>`;b+=`<circle cx="${60+x*50}" cy="${325-y*50}" r="7" fill="#24846b"/><text x="${70+x*50}" y="${315-y*50}" font-size="21">P</text><text x="390" y="335" font-size="19">x</text><text x="43" y="15" font-size="19">y</text>`;return reasoningSvg(b,`Coördinatenrooster met x en y van 0 tot 6. P ligt bij x=${x}, y=${y}.`,370)}
richRegister('C5','point-read','Een coördinaat aflezen',1,'rooster','grid',()=>{const x=randInt(1,5),y=randInt(1,5);return richNum('Wat is de y-coördinaat van P?',y,`Lees de hoogte van P op de verticale y-as: ${y}. De horizontale plaats hoort bij x.`,{x,y},{visual:richGridPoint(x,y)})},v=>v.y,true);
richRegister('C5','translation','Een punt verschuiven',2,'roosterroute','grid',()=>{const x=randInt(1,3),y=randInt(1,3),dx=randInt(1,3);return richNum(`P wordt ${dx} vakjes naar rechts en 2 omhoog verplaatst. Wat is de nieuwe x-coördinaat?`,x+dx,`Naar rechts verandert x: ${x} + ${dx} = ${x+dx}. Omhoog verandert alleen y.`,{x,y,dx},{visual:richGridPoint(x,y)})},v=>v.x+v.dx,true);
richRegister('C5','reflection','Een punt spiegelen in een verticale lijn',3,'spiegelrooster','grid',()=>{const x=randInt(1,2),y=randInt(1,5),line=3;return richNum('P wordt gespiegeld in de verticale lijn x = 3. Wat is de x-coördinaat van het spiegelbeeld?',6-x,`P ligt ${3-x} vakjes links van x = 3. Het spiegelbeeld ligt even ver rechts: 3 + ${3-x} = ${6-x}.`,{x,y,line},{visual:richGridPoint(x,y)})},v=>2*v.line-v.x);
richRegister('C5','right-angle-rest','Een rechte hoek aanvullen',2,'hoekmeting','text',()=>{const a=randInt(2,7)*10;return richNum(`Een rechte hoek van 90° wordt in twee hoeken verdeeld. Eén hoek is ${a}°. Hoe groot is de andere hoek?`,90-a,`De twee hoeken vormen samen 90°. Trek ${a}° af: ${90-a}°.`,{a},{unit:'°'})},v=>90-v.a,true);
richRegister('C5','triangle-angle','De derde hoek van een driehoek',2,'driehoek','table',()=>{const a=randInt(3,6)*10,b=randInt(3,7)*10;return richNum('Hoe groot is de derde hoek van de driehoek?',180-a-b,`De hoeken van een driehoek zijn samen 180°. Dus 180 − ${a} − ${b} = ${180-a-b}°.`,{a,b},{unit:'°',visual:richTable('Hoeken',[['Hoek A',`${a}°`],['Hoek B',`${b}°`]])})},v=>180-(v.a+v.b),true);
richRegister('C5','rotation','Een aantal kwartslagen naar graden',2,'draaiing','text',()=>{const n=randInt(1,7);return richNum(`Een wiel draait ${n} kwartslagen in dezelfde richting. Hoeveel graden draait het in totaal? Tel volledige rondes mee.`,90*n,`Een kwartslag is 90°. ${n} × 90 = ${90*n}°.`,{n},{unit:'°'})},v=>v.n*360/4,true);
richRegister('C5','drawing-length','Een werkelijke lengte naar de tekening',2,'bouwtekening','scale',()=>{const scale=pick([50,100,200]),meters=randInt(3,12);return richNum(`Een muur is ${meters} m lang. Hoeveel centimeter is dat op een tekening met schaal 1 : ${scale}?`,meters*100/scale,`Zet ${meters} m om in ${meters*100} cm en deel door ${scale}.`,{scale,meters},{unit:'cm'})},v=>v.meters/(v.scale/100),true);
richRegister('C5','recover-scale','De schaal uit twee overeenkomstige lengtes',3,'modelbouw','table',()=>{const cm=randInt(3,8),scale=pick([20,50,100]),real=cm*scale;return richNum('De schaal is 1 : □. Welk getal hoort in het vak?',scale,`Beide maten staan in centimeters. Deel de werkelijke lengte ${real} door de modellengte ${cm}: ${scale}.`,{cm,real},{visual:richTable('Overeenkomstige lengtes',[['Model',`${cm} cm`],['Werkelijk',`${real} cm`]])})},v=>v.real/v.cm,true);
richRegister('C5','top-view','Aantal bezette vakken in een bovenaanzicht',3,'blokjesbouwsel','height-map',()=>{const heights=[randInt(1,4),0,randInt(1,4),randInt(1,4),randInt(1,4),0];return richNum('De tabel geeft per vak het aantal opgestapelde blokjes. Een 0 is leeg. Hoeveel vakken zijn in het bovenaanzicht bezet?',4,'In een bovenaanzicht telt elke niet-lege stapel als één bezet vak. De hoogte van de stapel verandert dat niet.',{heights},{visual:reasoningTable(['Rij','Links','Midden','Rechts'],[['A',...heights.slice(0,3)],['B',...heights.slice(3)]],'Hoogtes per vak')})},v=>v.heights.filter(n=>n>0).length);
richRegister('C5','manhattan','Een route langs roosterlijnen',3,'stratenplan','table',()=>{const x1=randInt(1,3),y1=randInt(1,3),x2=randInt(5,8),y2=randInt(5,8),block=100;return richNum('Je mag alleen horizontaal en verticaal langs het rooster lopen. Elk vak is 100 m breed en hoog. Hoeveel meter is een kortste route?',(x2-x1+y2-y1)*100,`Je moet ${x2-x1} vakken horizontaal en ${y2-y1} verticaal afleggen. Samen ${x2-x1+y2-y1} vakken van 100 m.`,{x1,y1,x2,y2,block},{unit:'m',visual:richTable('Coördinaten',[['Start',`(${x1}, ${y1})`],['Doel',`(${x2}, ${y2})`]])})},v=>(Math.abs(v.x2-v.x1)+Math.abs(v.y2-v.y1))*v.block);
// D1 — informatie uit grafieken, legenda en tabellen.
function richBars(labels,values,title,unit='aantal'){const c=simpleBarChartSVG(labels,values,{title,unit,minorStep:5,majorStep:10});return {visual:c.html,visualMeta:c.meta}}
function richLine(labels,values,title,unit='aantal'){const c=simpleLineChartSVG(labels,values,{title,unit,minorStep:5,majorStep:10});return {visual:c.html,visualMeta:c.meta}}
richRegister('D1','bar-difference','Verschil tussen twee staven aflezen',2,'uitleenbalie','bar',()=>{const a=randInt(3,8)*5,b=a+randInt(2,5)*5;return richNum('Hoeveel meer boeken zijn dinsdag dan maandag uitgeleend?',b-a,`Lees dinsdag (${b}) en maandag (${a}) af. Trek af: ${b} − ${a} = ${b-a}.`,{a,b},{...richBars(['Ma','Di'],[a,b],'Uitgeleende boeken')})},v=>v.b-v.a);
richRegister('D1','bar-total','Een totaal uit meerdere staven',2,'sportinschrijving','bar',()=>{const values=[randInt(3,7)*5,randInt(3,7)*5,randInt(3,7)*5];return richNum('Hoeveel inschrijvingen zijn er in totaal?',values.reduce((a,b)=>a+b,0),`Tel de drie afgelezen aantallen op: ${values.join(' + ')} = ${values.reduce((a,b)=>a+b,0)}.`,{values},{...richBars(['Voetbal','Dans','Zwemmen'],values,'Inschrijvingen')})},v=>v.values.reduce((a,b)=>a+b,0));
richRegister('D1','line-increase','Toename tussen twee meetmomenten',2,'plantgroei','line',()=>{const a=randInt(2,5)*5,b=a+10,c=b+randInt(1,4)*5;return richNum('Hoeveel centimeter groeit de plant van week 1 tot week 3?',c-a,`Trek de beginhoogte ${a} af van de eindhoogte ${c}: ${c-a} cm. De tussenmeting tel je niet bij de hoogte op.`,{a,b,c},{unit:'cm',...richLine(['1','2','3'],[a,b,c],'Planthoogte per week','cm')})},v=>v.c-v.a);
richRegister('D1','cumulative','Een interval uit cumulatieve tellingen',3,'kaartverkoop','table',()=>{const a=randInt(3,9)*10,b=a+randInt(3,8)*5;return richNum('Hoeveel kaarten zijn tussen 12.00 en 14.00 verkocht?',b-a,`De tabel bevat totalen sinds opening. Neem het verschil: ${b} − ${a} = ${b-a}.`,{a,b},{visual:richTable('Totaal verkocht sinds opening',[['12.00',a],['14.00',b]])})},v=>v.b-v.a);
richRegister('D1','two-way-table','Een tabel met twee kenmerken combineren',3,'schoolvervoer','table',()=>{const a=randInt(10,25),b=randInt(10,25),c=randInt(5,15),d=randInt(5,15);return richNum('Hoeveel leerlingen uit beide klassen komen samen met de fiets?',a+b,`Gebruik alleen de kolom Fiets: ${a} + ${b} = ${a+b}. De lopers tellen niet mee.`,{a,b,c,d},{visual:reasoningTable(['Klas','Fiets','Lopen'],[['A',a,c],['B',b,d]],'Vervoer')})},v=>v.a+v.b);
richRegister('D1','relative-chart','Een aandeel uit grafiekwaarden',3,'bestellingen','bar',()=>{const a=pick([20,30,40]),b=100-a;return richNum('Hoeveel procent van de bestellingen is vegetarisch?',a,`Lees ${a} vegetarische en ${b} overige bestellingen af. Totaal 100, dus ${a}%.`,{a,b},{unit:'%',...richBars(['Vegetarisch','Overig'],[a,b],'Bestellingen')})},v=>v.a/(v.a+v.b)*100);
richRegister('D1','legend-value','Een pictogramlegenda gebruiken',2,'bezoekentelling','pictogram',()=>{const icons=randInt(3,7),each=pick([5,10,20]);const visual=reasoningSvg(`<text x="25" y="32" font-size="20">Elk rondje = ${each} bezoekers</text>`+Array.from({length:icons},(_,i)=>`<circle cx="${40+i*58}" cy="90" r="15" fill="#24846b"/>`).join(''),`${icons} rondjes; elk rondje staat voor ${each} bezoekers.`,140);return richNum('Hoeveel bezoekers stelt deze rij voor?',icons*each,`Er staan ${icons} symbolen. Elk telt voor ${each}: ${icons} × ${each} = ${icons*each}.`,{icons,each},{visual})},v=>v.icons*v.each);
richRegister('D1','table-interpolate','Een tussenwaarde bij expliciet gelijkmatig verloop',3,'vullen','table',()=>{const rate=pick([2,3,4]),start=randInt(5,15),t=5;return richNum('De hoeveelheid neemt gelijkmatig toe. Hoeveel liter is er na 5 minuten?',start+5*rate,`In 10 minuten komt er ${10*rate} L bij. In de helft van die tijd komt er ${5*rate} L bij, boven op ${start} L.`,{rate,start},{unit:'L',visual:richTable('Metingen',[['0 min',`${start} L`],['10 min',`${start+10*rate} L`]])})},v=>(v.start+(v.start+10*v.rate))/2);
richRegister('D1','threshold-data','Meetdagen boven een grens tellen',2,'luchtmetingen','table',()=>{const values=[15,20,25,30,35],limit=pick([20,25,30]);return richNum(`Op hoeveel meetdagen is de waarde strikt hoger dan ${limit}?`,values.filter(v=>v>limit).length,`Gelijk aan ${limit} telt niet mee. Tel alleen de waarden ${values.filter(v=>v>limit).join(', ')}.`,{values,limit},{visual:reasoningTable(['Dag','Waarde'],values.map((v,i)=>[i+1,v]),'Meetreeks')})},v=>v.values.reduce((n,x)=>n+(x>v.limit?1:0),0));
richRegister('D1','missing-category','Een ontbrekende categorie uit een totaal',3,'bezoekersverdeling','table',()=>{const a=randInt(2,6)*10,b=randInt(2,6)*10,c=randInt(2,6)*10;return richNum(`Er zijn ${a+b+c} bezoekers in totaal. Hoeveel horen bij categorie C? Iedere bezoeker hoort bij precies één categorie.`,c,`Trek de bekende groepen van het totaal af: ${a+b+c} − ${a} − ${b} = ${c}.`,{a,b,total:a+b+c},{visual:richTable('Categorieën',[['A',a],['B',b],['C','?']])})},v=>v.total-(v.a+v.b));
// D2 — samenvatten, wegen en uitspraken beoordelen.
richRegister('D2','range','Het verschil tussen maximum en minimum',2,'dagtemperaturen','table',()=>{const values=[randInt(1,5),randInt(6,10),randInt(11,15),randInt(7,10)];return richNum('Wat is het verschil tussen de hoogste en laagste temperatuur?',Math.max(...values)-Math.min(...values),`Hoogste: ${Math.max(...values)} °C. Laagste: ${Math.min(...values)} °C. Het verschil is ${Math.max(...values)-Math.min(...values)} °C.`,{values},{unit:'°C',visual:richTable('Dagmaxima',values.map((v,i)=>[`Dag ${i+1}`,`${v} °C`]))})},v=>[...v.values].sort((a,b)=>a-b).at(-1)-[...v.values].sort((a,b)=>a-b)[0]);
richRegister('D2','median','Het middelste getal na ordenen',2,'wachttijden','table',()=>{const base=randInt(3,8),values=shuffle([base,base+2,base+4,base+7,base+12]);return richNum('Zet de vijf wachttijden in gedachten op volgorde. Wat is de middelste wachttijd?',base+4,`Geordend: ${[...values].sort((a,b)=>a-b).join(', ')}. De derde van vijf is de middelste: ${base+4} minuten.`,{values},{unit:'min',visual:richTable('Wachttijd per persoon',values.map((v,i)=>[i+1,`${v} min`]))})},v=>[...v.values].sort((a,b)=>a-b)[2]);
richRegister('D2','frequency-mean','Een gemiddelde uit een frequentietabel',3,'gezinsgrootte','table',()=>{const a=randInt(2,6),b=randInt(2,6),n=a+b;return richNum('Wat is het gemiddelde aantal kinderen per gezin? Geef zo nodig een breuk.',(a+3*b)/n,`${a} gezinnen hebben 1 kind en ${b} gezinnen 3 kinderen. Deel het totaal ${a+3*b} door ${n} gezinnen.`,{a,b},{visual:reasoningTable(['Kinderen per gezin','Aantal gezinnen'],[[1,a],[3,b]],'Onderzoek'),...richFraction(a+3*b,n)})},v=>Array(v.a).fill(1).concat(Array(v.b).fill(3)).reduce((a,b)=>a+b,0)/(v.a+v.b));
richRegister('D2','mean-new-value','Een gemiddelde na een extra waarneming',3,'toetsscores','text',()=>{const n=4,mean=randInt(5,8),extra=mean+1;return richNum(`Vier scores hebben gemiddeld ${mean}. Er komt een vijfde score van ${extra} bij. Wat wordt het nieuwe gemiddelde?`,(4*mean+extra)/5,`De oude som is 4 × ${mean} = ${4*mean}. Tel ${extra} erbij en deel nu door vijf.`,{mean,extra})},v=>v.mean+(v.extra-v.mean)/5);
richRegister('D2','mean-correction','Een gemiddelde na correctie van één waarde',3,'meetregistratie','text',()=>{const n=5,mean=randInt(10,20),error=pick([5,10,15]);return richNum(`Vijf metingen hebben gemiddeld ${mean}. Eén meting blijkt ${error} te hoog genoteerd. Wat is het juiste gemiddelde?`,mean-error/5,`De totaalsom daalt met ${error}; verdeeld over vijf metingen daalt het gemiddelde met ${error/5}.`,{n,mean,error})},v=>(v.n*v.mean-v.error)/v.n);
richRegister('D2','weighted-average','Groepsgemiddelden met verschillende groottes',3,'klasresultaten','table',()=>{const a=10,b=20,x=randInt(5,7),y=x+1;return richNum('Wat is het gemiddelde van alle leerlingen samen? Geef zo nodig een breuk.',(a*x+b*y)/(a+b),`Bereken de gezamenlijke som: ${a} × ${x} + ${b} × ${y} = ${a*x+b*y}. Deel door ${a+b} leerlingen.`,{a,b,x,y},{visual:reasoningTable(['Groep','Aantal','Gemiddelde'],[['A',a,x],['B',b,y]],'Scores'),...richFraction(a*x+b*y,a+b)})},v=>(v.a*v.x+v.b*v.y)/(v.a+v.b));
richRegister('D2','outlier','Het effect van één hoge uitschieter',2,'reistijden','text',()=>richChoice('Vier reistijden zijn 10, 11, 12 en 13 minuten. Er komt één reistijd van 80 minuten bij. Wat gebeurt er met het gemiddelde?','Het stijgt.',['Het daalt.','Het blijft gelijk.','Dat is niet te bepalen.'],'80 ligt boven het oude gemiddelde van 11,5. De toevoeging trekt het gemiddelde omhoog.',{}),()=> 'Het stijgt.');
richRegister('D2','sample-bias','Een beperkte steekproef herkennen',3,'schoolenquete','text',()=>richChoice('Een school vraagt alleen leden van de voetbalclub welke sport zij het leukst vinden. Mag de school de uitkomst zonder meer gebruiken als voorkeur van alle leerlingen?','Nee, andere leerlingen zijn niet vertegenwoordigd.',['Ja, zolang iedereen uit de club antwoordt.','Ja, want een voorkeur is een getal.','Nee, enquêtes kunnen nooit iets zeggen.'],'De selectie hangt samen met de gevraagde sportvoorkeur. De voetbalclub hoeft geen afspiegeling van alle leerlingen te zijn.',{}),()=> 'Nee, andere leerlingen zijn niet vertegenwoordigd.');
richRegister('D2','same-average','Verschillende spreiding bij hetzelfde gemiddelde',3,'bezorgtijden','table',()=>{const m=randInt(10,20);return richChoice('Welke bezorger heeft de meest gelijkmatige tijden, gemeten met het verschil tussen hoogste en laagste?','Bezorger A.',['Bezorger B.','Beiden even gelijkmatig.','Niet te bepalen.'],`Beide gemiddelden zijn ${m}. Bij A is het verschil 2 minuten en bij B 10 minuten. Volgens de genoemde maat is A gelijkmatiger.`,{m},{visual:reasoningTable(['Bezorger','Rit 1','Rit 2','Rit 3'],[['A',m-1,m,m+1],['B',m-5,m,m+5]],'Minuten')})},()=> 'Bezorger A.');
richRegister('D2','mode','De meest voorkomende waarde uit een tabel',2,'schoenmaten','table',()=>{const size=randInt(36,41),freq=[3,8,5];return richNum('Welke schoenmaat komt het vaakst voor?',size+1,`Zoek de hoogste frequentie: 8 leerlingen. Die hoort bij maat ${size+1}.`,{size,freq},{visual:reasoningTable(['Maat','Aantal'],freq.map((f,i)=>[size+i,f]),'Schoenmaten')})},v=>v.size+v.freq.indexOf(Math.max(...v.freq)));
// D3 — regels lezen, reconstrueren en onder voorwaarden toepassen.
richRegister('D3','substitute','Een formule invullen met expliciete eenheden',2,'taxirit','formula',()=>{const base=randInt(3,8),rate=randInt(2,5),km=randInt(4,12);return richNum(`Een taxi rekent prijs = ${base} + ${rate} × kilometers, in euro. Wat kost een rit van ${km} km?`,base+rate*km,`Vul ${km} in: ${base} + ${rate} × ${km} = € ${base+rate*km}.`,{base,rate,km},{unit:'€'})},v=>v.km*v.rate+v.base);
richRegister('D3','inverse-input','Een invoerwaarde uit een formule terugvinden',3,'huurkosten','formula',()=>{const base=randInt(3,8),rate=randInt(2,6),hours=randInt(3,10),total=base+rate*hours;return richNum(`Huurprijs = ${base} + ${rate} × aantal uren. De rekening is € ${total}. Hoeveel uur is gehuurd?`,hours,`Trek eerst het vaste bedrag af: ${total} − ${base} = ${total-base}. Deel door de uurprijs ${rate}: ${hours} uur.`,{base,rate,total},{unit:'uur'})},v=>(v.total-v.base)/v.rate);
richRegister('D3','rate-from-table','Een constante toename uit een tabel bepalen',3,'kopieerwerk','table',()=>{const rate=randInt(2,7),base=randInt(3,10),a=randInt(2,5),b=a+randInt(2,4);return richNum('De prijs bestaat uit een vast startbedrag plus een vast bedrag per boekje. Wat kost één extra boekje?',rate,`Het prijsverschil is ${rate*(b-a)} voor ${b-a} extra boekjes. Deel deze verschillen: € ${rate} per extra boekje.`,{a,b,c1:base+a*rate,c2:base+b*rate},{unit:'€',visual:reasoningTable(['Boekjes','Prijs in euro'],[[a,base+a*rate],[b,base+b*rate]],'Prijzen')})},v=>(v.c2-v.c1)/(v.b-v.a));
richRegister('D3','fixed-term','Betekenis van het vaste bedrag',2,'abonnement','formula',()=>{const base=randInt(5,15),rate=pick([2,3,4,5,6].filter(n=>n!==base));return richChoice(`Maandkosten = ${base} + ${rate} × aantal bezoeken. Wat betekent ${base}?`,'Het bedrag dat je ook bij nul bezoeken betaalt.',['De prijs per bezoek.','Het maximale aantal bezoeken.','De korting op de totale prijs.'],`Bij nul bezoeken is de variabele term nul. Er blijft € ${base} over als vast bedrag.`,{base,rate})},()=> 'Het bedrag dat je ook bij nul bezoeken betaalt.');
richRegister('D3','cost-difference','Het prijsverschil bij een veranderde invoer',2,'drukker','formula',()=>{const base=randInt(2,8),rate=randInt(2,6),extra=randInt(2,8);return richNum(`Prijs = ${base} + ${rate} × aantal posters. Je bestelt ${extra} posters meer. Hoeveel euro wordt de bestelling duurder?`,rate*extra,`Het vaste bedrag verandert niet. Alleen ${extra} extra posters à € ${rate} tellen mee: € ${rate*extra}.`,{base,rate,extra},{unit:'€'})},v=>(v.base+v.rate*(10+v.extra))-(v.base+v.rate*10));
richRegister('D3','budget-bound','Een maximaal geheel aantal binnen een budget',3,'huur-boten','formula',()=>{const base=randInt(3,8),rate=randInt(3,7),n=randInt(5,12),budget=base+rate*n+randInt(1,rate-1);return richNum(`Kosten = ${base} + ${rate} × aantal boten. Het budget is € ${budget}. Hoeveel hele boten kun je maximaal huren?`,n,`Na het vaste bedrag is € ${budget-base} beschikbaar. Deel door ${rate} en rond omlaag naar hele boten: ${n}.`,{base,rate,budget})},v=>{let n=0;while(v.base+v.rate*(n+1)<=v.budget)n++;return n});
richRegister('D3','equal-prices','Twee lineaire prijsregels gelijkstellen',4,'verhuurvergelijking','table',()=>{const a=randInt(2,6),cross=randInt(4,12),rate=randInt(3,5),b=a+cross;return richNum('Bij hoeveel uren zijn de twee prijzen gelijk?',cross,`B begint € ${b-a} hoger, maar is per uur € 1 goedkoper. Na ${cross} uur is het verschil ingehaald.`,{a,b,rate},{unit:'uur',visual:richTable('Prijs in euro; u = uren',[['A',`${a} + ${rate} × u`],['B',`${b} + ${rate-1} × u`]])})},v=>(v.b-v.a)/(v.rate-(v.rate-1)));
richRegister('D3','decreasing','Een afnemende voorraadregel gebruiken',2,'reservoir','formula',()=>{const start=randInt(10,20)*10,rate=randInt(3,8),time=randInt(3,9);return richNum(`Inhoud = ${start} − ${rate} × minuten, in liter. Hoeveel liter resteert na ${time} minuten?`,start-rate*time,`Elke minuut gaat ${rate} L weg. Trek na ${time} minuten ${rate*time} L van ${start} af.`,{start,rate,time},{unit:'L'})},v=>v.start-v.rate*v.time);
richRegister('D3','formula-match','Een situatie aan de juiste formule koppelen',3,'bezorgservice','formula',()=>{const base=randInt(3,8),rate=pick([2,3,4,5,6].filter(n=>n!==base)),correct=`kosten = ${base} + ${rate} × aantal kratten`;return richChoice(`Een levering heeft € ${base} vaste bezorgkosten en kost daarnaast € ${rate} per krat. Welke formule past?`,correct,[`kosten = ${base} × aantal kratten + ${rate}`,`kosten = (${base} + ${rate}) × aantal kratten`,`kosten = ${base} + ${rate} + aantal kratten`],`De bezorgkosten betaal je één keer. Alleen de prijs per krat wordt vermenigvuldigd met het aantal.`,{base,rate})},v=>`kosten = ${v.base} + ${v.rate} × aantal kratten`);
richRegister('D3','two-inputs','Een formule met twee aantallen toepassen',3,'theaterkaartjes','formula',()=>{const adult=randInt(8,15),child=randInt(3,7),a=randInt(2,5),c=randInt(2,6);return richNum(`Totale prijs = ${adult} × volwassenen + ${child} × kinderen. Wat kost een groep van ${a} volwassenen en ${c} kinderen?`,adult*a+child*c,`Volwassenen: € ${adult*a}. Kinderen: € ${child*c}. Tel de bedragen op: € ${adult*a+child*c}.`,{adult,child,a,c},{unit:'€'})},v=>v.adult*v.a+v.child*v.c);
// D4 — expliciete regels, figurale patronen en ontbrekende posities.
function richSquaresRow(n){return reasoningSvg(Array.from({length:n},(_,i)=>`<rect x="${25+i*50}" y="40" width="50" height="50" fill="#eaf6ff" stroke="#123b5d" stroke-width="3"/>`).join(''),`${n} vierkanten in één aaneengesloten rij. Buren delen een hele zijde.`,125)}
richRegister('D4','arithmetic-forward','Een verder gelegen term van een rekenrij',2,'stoelenrijen','table',()=>{const start=randInt(3,9),step=randInt(2,5),n=randInt(7,12);return richNum(`Elke volgende rij heeft precies ${step} stoelen meer. Hoeveel stoelen heeft rij ${n}?`,start+(n-1)*step,`Vanaf rij 1 maak je ${n-1} stappen. Dus ${start} + ${n-1} × ${step} = ${start+(n-1)*step}.`,{start,step,n},{visual:richTable('Zaal',[['Rij 1',start],['Rij 2',start+step],['Rij 3',start+2*step]])})},v=>v.start+v.step*(v.n-1));
richRegister('D4','arithmetic-backward','Een beginterm reconstrueren',3,'nummerreeks','text',()=>{const start=randInt(3,9),step=randInt(2,6),n=randInt(5,9),value=start+(n-1)*step;return richNum(`Een rij groeit steeds met ${step}. Het ${n}e getal is ${value}. Wat is het eerste getal?`,start,`Ga ${n-1} stappen terug: ${value} − ${n-1} × ${step} = ${start}.`,{step,n,value})},v=>v.value-(v.n-1)*v.step);
richRegister('D4','geometric','Een vermenigvuldigingspatroon voortzetten',2,'groeireeks','text',()=>{const start=randInt(2,5),factor=pick([2,3]),n=4;return richNum(`De regel is: vermenigvuldig telkens met ${factor}. De rij begint ${start}, ${start*factor}, ${start*factor**2}. Wat is het volgende getal?`,start*factor**3,`Vermenigvuldig de laatste waarde ${start*factor**2} met ${factor}: ${start*factor**3}.`,{start,factor})},v=>v.start*v.factor*v.factor*v.factor);
richRegister('D4','cycle-index','Een positie in een herhalend patroon',3,'lichtslinger','text',()=>{const n=randInt(4,12)*3+1;return richChoice(`Een lichtslinger herhaalt steeds rood, groen, blauw. Lampje 1 is rood. Welke kleur heeft lampje ${n}?`,'Rood.',['Groen.','Blauw.','Dat is niet te bepalen.'],`Het patroon heeft lengte 3. ${n} = ${Math.floor(n/3)} × 3 + 1; dit is weer de eerste kleur, rood.`,{n})},v=>['Rood.','Groen.','Blauw.'][(v.n-1)%3]);
richRegister('D4','matchsticks','Gedeelde zijden in een vierkantenrij',3,'luciferfiguur','diagram',()=>{const n=randInt(3,7);return richNum('Elke getekende zijde is één lucifer. Een gedeelde zijde telt één keer. Hoeveel lucifers zijn nodig?',3*n+1,`Het eerste vierkant vraagt 4 lucifers. Elk volgend vierkant voegt 3 toe, omdat één zijde al bestaat: 4 + ${n-1} × 3 = ${3*n+1}.`,{n},{visual:richSquaresRow(n)})},v=>4*v.n-(v.n-1));
richRegister('D4','triangular','Een groeiend aantal per rij optellen',3,'stapelblikken','text',()=>{const n=randInt(4,9);return richNum(`Een driehoekige stapel heeft ${n} rijen. Bovenaan staat 1 blik, daaronder 2, dan 3, enzovoort tot ${n}. Hoeveel blikken zijn er samen?`,n*(n+1)/2,`Tel de aantallen in de rijen op: ${Array.from({length:n},(_,i)=>i+1).join(' + ')} = ${n*(n+1)/2}.`,{n})},v=>Array.from({length:v.n},(_,i)=>i+1).reduce((a,b)=>a+b,0));
richRegister('D4','growing-differences','Een expliciet toenemende sprong volgen',3,'getallenpatroon','text',()=>{const start=randInt(2,8),jump=randInt(2,5),vals=[start,start+jump,start+2*jump+1,start+3*jump+3];return richNum(`De sprongen nemen telkens met 1 toe, beginnend met +${jump}. Welk getal volgt op ${vals.join(', ')}?`,vals[3]+jump+3,`De sprongen zijn ${jump}, ${jump+1}, ${jump+2}. De volgende is ${jump+3}. Tel die bij ${vals[3]} op.`,{start,jump})},v=>v.start+4*v.jump+6);
richRegister('D4','alternating','Twee afwisselende bewerkingen volgen',3,'rekenroute','text',()=>{const a=randInt(2,6),b=randInt(2,5);return richNum(`Vanaf ${a} wisselen de stappen steeds af: +${b}, dan ×2, dan +${b}, dan ×2. Welk getal bereik je na deze vier stappen?`,((a+b)*2+b)*2,`Volg de stappen: ${a} → ${a+b} → ${(a+b)*2} → ${(a+b)*2+b} → ${((a+b)*2+b)*2}.`,{a,b})},v=>4*v.a+6*v.b);
richRegister('D4','missing-middle','Een ontbrekende term met gelijke sprongen',2,'rekenrij','text',()=>{const a=randInt(3,15),step=randInt(2,8);return richNum(`De sprongen zijn gelijk: ${a}, □, ${a+2*step}. Welk getal ontbreekt?`,a+step,`Van eerste naar derde zijn twee gelijke sprongen. Het verschil ${2*step} gedeeld door 2 is ${step}. Tel één sprong bij ${a}.`,{a,last:a+2*step})},v=>(v.a+v.last)/2);
richRegister('D4','grid-border','Randvakken van een vierkant patroon tellen',3,'tegelpatroon','text',()=>{const n=randInt(4,9);return richNum(`Een vierkant rooster heeft ${n} bij ${n} vakjes. Alleen de buitenste rand vakjes wordt gekleurd. Hoeveel vakjes zijn gekleurd? Tel hoeken één keer.`,4*n-4,`Boven en onder elk ${n}; links en rechts elk ${n-2} extra. Samen 2 × ${n} + 2 × ${n-2} = ${4*n-4}.`,{n})},v=>v.n**2-(v.n-2)**2);
